    "signed_on" date,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_variations_variation_amount_has_currency" CHECK (
        (
            ("amount_change" IS NULL)
            OR ("currency_id" IS NOT NULL)
        )
    ),
    CONSTRAINT "chk_variations_variation_note_has_language" CHECK (
        (
            ("note" IS NULL)
            OR ("note_language_id" IS NOT NULL)
        )
    ),
    PRIMARY KEY ("id")
);

CREATE TABLE "community"."actors" (
    "account_id" uuid,
    "avatar_id" uuid,
    "country_id" uuid,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "display_name" varchar(100),
    "first_seen_at" timestamptz NOT NULL,
    "handle" varchar(30),
    "id" uuid NOT NULL,
    "kind" text NOT NULL,
    "language_id" uuid,
    "last_seen_at" timestamptz NOT NULL,
    "status" text NOT NULL,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_actors_member_has_account" CHECK (
        (
            ("kind" <> 'member')
            OR ("account_id" IS NOT NULL)
        )
    ),
    CONSTRAINT "chk_actors_handle_is_for_members" CHECK (
        (
            ("handle" IS NULL)
            OR ("kind" = 'member')
        )
    ),
    CONSTRAINT "chk_actors_kind_enum" CHECK ("kind" IN ('member', 'visitor')),
    CONSTRAINT "chk_actors_status_enum" CHECK ("status" IN ('active', 'blocked', 'closed')),
    PRIMARY KEY ("id")
);

CREATE TABLE "community"."attachments" (
    "asset_id" uuid NOT NULL,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "id" uuid NOT NULL,
    "post_country_id" uuid NOT NULL,
    "post_id" uuid NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "community"."blocks" (
    "account_id" uuid NOT NULL,
    "case_id" uuid,
    "created_at" timestamptz NOT NULL,
    "decided_by" uuid NOT NULL,
    "deleted_at" timestamptz,
    "from_on" date NOT NULL,
    "id" uuid NOT NULL,
    "reason_term" uuid NOT NULL,
    "to_on" date,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_blocks_block_dates_are_ordered" CHECK (
        (
            ("from_on" IS NULL)
            OR ("to_on" IS NULL)
            OR ("from_on" <= "to_on")
        )
    ),
    PRIMARY KEY ("id")
);

CREATE TABLE "community"."cases" (
    "created_at" timestamptz NOT NULL,
    "decided_at" timestamptz,
    "decision" text,
    "deleted_at" timestamptz,
    "id" uuid NOT NULL,
    "post_country_id" uuid NOT NULL,
    "post_id" uuid NOT NULL,
    "reason" varchar(4000),
    "reviewer_account_id" uuid,
    "state" text NOT NULL,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_cases_decision_enum" CHECK (
        "decision" IN ('approve', 'escalate', 'reject', 'remove')
    ),
    CONSTRAINT "chk_cases_state_enum" CHECK (
        "state" IN ('decided', 'escalated', 'in-review', 'open')
    ),
    PRIMARY KEY ("id")
);

CREATE TABLE "community"."checks" (
    "case_id" uuid NOT NULL,
    "category_term" uuid,
    "checked_at" timestamptz NOT NULL,
    "checker" text NOT NULL,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "id" uuid NOT NULL,
    "score" double precision,
    "updated_at" timestamptz NOT NULL,
    "verdict" text NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_checks_checker_enum" CHECK ("checker" IN ('ai', 'human', 'rules')),
    CONSTRAINT "chk_checks_verdict_enum" CHECK ("verdict" IN ('fail', 'flag', 'pass')),
    PRIMARY KEY ("id")
);

CREATE TABLE "community"."consents" (
    "actor_id" uuid NOT NULL,
    "country_id" uuid,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "given_at" timestamptz NOT NULL,
    "id" uuid NOT NULL,
    "key_id" uuid NOT NULL,
    "purpose_term" uuid NOT NULL,
    "text_version" varchar(100) NOT NULL,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    "withdrawn_at" timestamptz,
    PRIMARY KEY ("id")
);

CREATE TABLE "community"."devices" (
    "actor_id" uuid NOT NULL,
    "app_version" varchar(100),
    "attestation" text NOT NULL,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "fingerprint_hash" char(64) NOT NULL,
    "first_seen_at" timestamptz NOT NULL,
    "id" uuid NOT NULL,
    "last_seen_at" timestamptz NOT NULL,
    "platform" text NOT NULL,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_devices_attestation_enum" CHECK (
        "attestation" IN ('failed', 'none', 'passed', 'unavailable')
    ),
    CONSTRAINT "chk_devices_platform_enum" CHECK ("platform" IN ('android', 'ios', 'web')),
    PRIMARY KEY ("id")
);

CREATE TABLE "community"."dispatches" (
    "created_at" timestamptz NOT NULL,
    "device_id" uuid NOT NULL,
    "id" uuid NOT NULL,
    "notification_created_at" timestamptz NOT NULL,
    "notification_id" uuid NOT NULL,
    "opened_at" timestamptz,
    "sent_at" timestamptz,
    "state" text NOT NULL,
    "subscription_id" uuid NOT NULL,
    CONSTRAINT "chk_dispatches_state_enum" CHECK ("state" IN ('failed', 'opened', 'queued', 'sent')),
    PRIMARY KEY ("id", "created_at")
)
PARTITION BY
    RANGE ("created_at");

