CREATE TABLE "community"."places" (
    "actor_id" uuid NOT NULL,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "feature_id" uuid NOT NULL,
    "id" uuid NOT NULL,
    "is_home" boolean NOT NULL,
    "label" varchar(100) NOT NULL,
    "position" integer,
    "suggestion_term" uuid,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "community"."posts" (
    "actor_id" uuid NOT NULL,
    "body" varchar(20000),
    "country_id" uuid NOT NULL,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "device_id" uuid,
    "id" uuid NOT NULL,
    "identity_id" uuid,
    "kind" text NOT NULL,
    "language_id" uuid,
    "parent_id" uuid,
    "proof_id" uuid,
    "published_at" timestamptz,
    "rating" integer,
    "state" text NOT NULL,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_posts_published_post_has_time" CHECK (
        (
            ("state" <> 'published')
            OR ("published_at" IS NOT NULL)
        )
    ),
    CONSTRAINT "chk_posts_kind_enum" CHECK (
        "kind" IN ('comment', 'question', 'report', 'review')
    ),
    CONSTRAINT "chk_posts_state_enum" CHECK (
        "state" IN (
            'draft',
            'pending',
            'published',
            'rejected',
            'removed'
        )
    ),
    PRIMARY KEY ("id", "country_id")
)
PARTITION BY
    HASH ("country_id");

