CREATE TABLE "community"."preferences" (
    "actor_id" uuid NOT NULL,
    "country_id" uuid,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "home_feature_id" uuid,
    "id" uuid NOT NULL,
    "language_id" uuid,
    "theme" text,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_preferences_theme_enum" CHECK ("theme" IN ('dark', 'light', 'system')),
    PRIMARY KEY ("id")
);

CREATE TABLE "community"."proofs" (
    "accuracy_meters" integer,
    "actor_id" uuid NOT NULL,
    "attestation_ok" boolean,
    "check" text NOT NULL,
    "coarse_cell" varchar(100),
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "device_id" uuid NOT NULL,
    "header_agrees" boolean,
    "id" uuid NOT NULL,
    "matched_feature_id" uuid,
    "mock_location_detected" boolean NOT NULL,
    "recorded_at" timestamptz NOT NULL,
    "travel_ok" boolean,
    "trust_score" double precision NOT NULL,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_proofs_check_enum" CHECK (
        "check" IN (
            'inside',
            'near',
            'outside',
            'suspected-mock',
            'unavailable'
        )
    ),
    PRIMARY KEY ("id")
);

CREATE TABLE "community"."reactions" (
    "actor_id" uuid NOT NULL,
    "article_id" uuid,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "id" uuid NOT NULL,
    "identity_id" uuid,
    "kind_term" uuid NOT NULL,
    "post_country_id" uuid,
    "post_id" uuid,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_reactions_reaction_has_one_subject" CHECK (
        (
            (
                ("post_id" IS NOT NULL)
                AND ("identity_id" IS NULL)
                AND ("article_id" IS NULL)
            )
            OR (
                ("post_id" IS NULL)
                AND ("identity_id" IS NOT NULL)
                AND ("article_id" IS NULL)
            )
            OR (
                ("post_id" IS NULL)
                AND ("identity_id" IS NULL)
                AND ("article_id" IS NOT NULL)
            )
        )
    ),
    PRIMARY KEY ("id")
);

CREATE TABLE "community"."replies" (
    "body" varchar(20000) NOT NULL,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "id" uuid NOT NULL,
    "language_id" uuid NOT NULL,
    "post_country_id" uuid NOT NULL,
    "post_id" uuid NOT NULL,
    "published_at" timestamptz,
    "received_at" timestamptz NOT NULL,
    "respondent_id" uuid NOT NULL,
    "status" text NOT NULL,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_replies_status_enum" CHECK (
        "status" IN ('published', 'received', 'withdrawn')
    ),
    PRIMARY KEY ("id")
);

CREATE TABLE "community"."subscriptions" (
    "actor_id" uuid NOT NULL,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "id" uuid NOT NULL,
    "identity_id" uuid NOT NULL,
    "kind" text NOT NULL,
    "revoked_at" timestamptz,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_subscriptions_kind_enum" CHECK ("kind" IN ('alerts', 'follow')),
    PRIMARY KEY ("id")
);

CREATE TABLE "community"."tokens" (
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "device_id" uuid NOT NULL,
    "enabled_at" timestamptz NOT NULL,
    "id" uuid NOT NULL,
    "provider" text NOT NULL,
    "revoked_at" timestamptz,
    "token" varchar(1000) NOT NULL,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_tokens_provider_enum" CHECK ("provider" IN ('apns', 'fcm', 'onesignal')),
    PRIMARY KEY ("id")
);

CREATE TABLE "community"."views" (
    "article_id" uuid,
    "country_id" uuid,
    "created_at" timestamptz NOT NULL,
    "day" date NOT NULL,
    "id" uuid NOT NULL,
    "identity_id" uuid,
    "post_country_id" uuid,
    "post_id" uuid,
    "visitor_hash" char(64) NOT NULL,
    CONSTRAINT "chk_views_view_has_one_subject" CHECK (
        (
            (
                ("identity_id" IS NOT NULL)
                AND ("article_id" IS NULL)
                AND ("post_id" IS NULL)
            )
            OR (
                ("identity_id" IS NULL)
                AND ("article_id" IS NOT NULL)
                AND ("post_id" IS NULL)
            )
            OR (
                ("identity_id" IS NULL)
                AND ("article_id" IS NULL)
                AND ("post_id" IS NOT NULL)
            )
        )
    ),
    PRIMARY KEY ("id", "day")
)
PARTITION BY
    RANGE ("day");

