CREATE TABLE "economy"."baskets" (
    "code" varchar(255) NOT NULL,
    "collection_id" uuid,
    "country_id" uuid NOT NULL,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "from_year" integer,
    "id" uuid NOT NULL,
    "to_year" integer,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "economy"."codes" (
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "good_id" uuid NOT NULL,
    "id" uuid NOT NULL,
    "scheme_term" uuid NOT NULL,
    "value" varchar(50) NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "economy"."compositions" (
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "good_id" uuid NOT NULL,
    "id" uuid NOT NULL,
    "input_id" uuid NOT NULL,
    "quantity" double precision NOT NULL,
    "unit_id" uuid NOT NULL,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_compositions_composition_is_not_itself" CHECK (("good_id" <> "input_id")),
    PRIMARY KEY ("id")
);

CREATE TABLE "economy"."crosswalks" (
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "from_scheme_term" uuid NOT NULL,
    "from_value" varchar(50) NOT NULL,
    "id" uuid NOT NULL,
    "kind" text NOT NULL,
    "to_scheme_term" uuid NOT NULL,
    "to_value" varchar(50) NOT NULL,
    CONSTRAINT "chk_crosswalks_kind_enum" CHECK ("kind" IN ('exact', 'partial')),
    PRIMARY KEY ("id")
);

CREATE TABLE "economy"."goods" (
    "code" varchar(255) NOT NULL,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "id" uuid NOT NULL,
    "kind" text NOT NULL,
    "parent_id" uuid,
    "size" double precision,
    "size_unit_id" uuid,
    "standard_term" uuid,
    "status" text NOT NULL,
    "unit_id" uuid,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_goods_good_is_not_its_own_parent" CHECK (("id" <> "parent_id")),
    CONSTRAINT "chk_goods_size_has_unit" CHECK (
        (
            ("size" IS NULL)
            OR ("size_unit_id" IS NOT NULL)
        )
    ),
    CONSTRAINT "chk_goods_kind_enum" CHECK ("kind" IN ('good', 'service', 'works')),
    CONSTRAINT "chk_goods_status_enum" CHECK ("status" IN ('active', 'retired')),
    PRIMARY KEY ("id")
);

CREATE TABLE "economy"."names" (
    "country_id" uuid,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "good_id" uuid NOT NULL,
    "id" uuid NOT NULL,
    "kind" text NOT NULL,
    "language_id" uuid NOT NULL,
    "text" varchar(1000) NOT NULL,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_names_kind_enum" CHECK (
        "kind" IN ('alternative', 'plural', 'preferred', 'short')
    ),
    PRIMARY KEY ("id")
);

CREATE TABLE "economy"."prices" (
    "amount" bigint,
    "basis" text NOT NULL,
    "collection_id" uuid,
    "country_id" uuid NOT NULL,
    "created_at" timestamptz NOT NULL,
    "currency_id" uuid NOT NULL,
    "deleted_at" timestamptz,
    "ends_on" date,
    "feature_id" uuid,
    "from_year" integer,
    "good_id" uuid NOT NULL,
    "id" uuid NOT NULL,
    "kind_term" uuid NOT NULL,
    "revision" integer NOT NULL,
    "starts_on" date,
    "status" text NOT NULL,
    "supersedes_id" uuid,
    "to_year" integer,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_prices_price_period_is_ordered" CHECK (
        (
            ("from_year" IS NULL)
            OR ("to_year" IS NULL)
            OR ("from_year" <= "to_year")
        )
    ),
    CONSTRAINT "chk_prices_price_dates_are_ordered" CHECK (
        (
            ("starts_on" IS NULL)
            OR ("ends_on" IS NULL)
            OR ("starts_on" <= "ends_on")
        )
    ),
    CONSTRAINT "chk_prices_basis_enum" CHECK (
        "basis" IN (
            'aggregated',
            'estimated',
            'measured',
            'modelled',
            'projected'
        )
    ),
    CONSTRAINT "chk_prices_status_enum" CHECK (
        "status" IN (
            'estimated',
            'final',
            'missing',
            'projected',
            'provisional',
            'revised',
            'suppressed'
        )
    ),
    PRIMARY KEY ("id", "country_id")
)
PARTITION BY
    HASH ("country_id");

CREATE TABLE "economy"."prices_h00" PARTITION OF "economy"."prices" FOR
VALUES
WITH
    (MODULUS 16, REMAINDER 0);

CREATE TABLE "economy"."prices_h01" PARTITION OF "economy"."prices" FOR
