);

CREATE TABLE "election"."attachments" (
    "article_id" uuid,
    "asset_id" uuid,
    "candidate_id" uuid,
    "contest_id" uuid,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "election_id" uuid,
    "end_second" double precision,
    "id" uuid NOT NULL,
    "position" integer,
    "purpose_term" uuid NOT NULL,
    "start_second" double precision,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_attachments_attachment_has_one_row" CHECK (
        (
            (
                ("election_id" IS NOT NULL)
                AND ("contest_id" IS NULL)
                AND ("candidate_id" IS NULL)
            )
            OR (
                ("election_id" IS NULL)
                AND ("contest_id" IS NOT NULL)
                AND ("candidate_id" IS NULL)
            )
            OR (
                ("election_id" IS NULL)
                AND ("contest_id" IS NULL)
                AND ("candidate_id" IS NOT NULL)
            )
        )
    ),
    CONSTRAINT "chk_attachments_attachment_has_one_media" CHECK (
        (
            (
                ("asset_id" IS NOT NULL)
                AND ("article_id" IS NULL)
            )
            OR (
                ("asset_id" IS NULL)
                AND ("article_id" IS NOT NULL)
            )
        )
    ),
    PRIMARY KEY ("id")
);

