CREATE TABLE "election"."elections" (
    "authority_id" uuid,
    "code" varchar(255) NOT NULL,
    "country_id" uuid NOT NULL,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "event_id" uuid,
    "from_year" integer NOT NULL,
    "held_on" date,
    "id" uuid NOT NULL,
    "identity_kind" text NOT NULL DEFAULT 'election',
    "kind_term" uuid NOT NULL,
    "parent_id" uuid,
    "status" text NOT NULL,
    "template_id" uuid,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_elections_election_kind" CHECK (("identity_kind" = 'election')),
    CONSTRAINT "chk_elections_identity_kind_enum" CHECK (
        "identity_kind" IN (
            'app',
            'bill',
            'coalition',
            'collection',
            'country',
            'currency',
            'debt',
            'election',
            'entity',
            'era',
            'event',
            'feature',
            'function',
            'fund',
            'hierarchy',
            'indicator',
            'individual',
            'instrument',
            'language',
            'level',
            'metric',
            'occurrence',
            'office',
            'pattern',
            'position',
            'procedure',
            'procurement',
            'product',
            'project',
            'service',
            'template',
            'timezone',
            'unit'
        )
    ),
    CONSTRAINT "chk_elections_status_enum" CHECK ("status" IN ('annulled', 'held', 'scheduled')),
    PRIMARY KEY ("id")
);

CREATE TABLE "election"."forms" (
    "asset_id" uuid,
    "contest_id" uuid NOT NULL,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "feature_id" uuid,
    "form_term" uuid NOT NULL,
    "id" uuid NOT NULL,
    "published_on" date,
    "station_id" uuid,
    "status" text NOT NULL,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_forms_form_has_one_place" CHECK (
        (
            (
                ("station_id" IS NOT NULL)
                AND ("feature_id" IS NULL)
            )
            OR (
                ("station_id" IS NULL)
                AND ("feature_id" IS NOT NULL)
            )
        )
    ),
    CONSTRAINT "chk_forms_status_enum" CHECK ("status" IN ('final', 'provisional')),
    PRIMARY KEY ("id")
);

CREATE TABLE "election"."results" (
    "basis" text NOT NULL,
    "candidate_id" uuid,
    "choice_id" uuid,
    "collection_id" uuid,
    "country_id" uuid NOT NULL,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "feature_id" uuid NOT NULL,
    "form_id" uuid,
    "id" uuid NOT NULL,
    "revision" integer NOT NULL,
    "status" text NOT NULL,
    "supersedes_id" uuid,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    "votes" integer,
    CONSTRAINT "chk_results_result_has_one_option" CHECK (
        (
            (
                ("candidate_id" IS NOT NULL)
                AND ("choice_id" IS NULL)
            )
            OR (
                ("candidate_id" IS NULL)
                AND ("choice_id" IS NOT NULL)
            )
        )
    ),
    CONSTRAINT "chk_results_basis_enum" CHECK (
        "basis" IN (
            'aggregated',
            'estimated',
            'measured',
            'modelled',
            'projected'
        )
    ),
    CONSTRAINT "chk_results_status_enum" CHECK (
        "status" IN (
            'estimated',
            'final',
            'missing',
            'projected',
            'provisional',
            'revised',
            'suppressed'
        )
    ),
    PRIMARY KEY ("id", "country_id")
)
PARTITION BY
    HASH ("country_id");

