    CONSTRAINT "chk_folders_access_enum" CHECK (
        "access" IN ('internal', 'private', 'public', 'restricted')
    ),
    PRIMARY KEY ("id")
);

CREATE TABLE "filesystem"."formats" (
    "code" varchar(255) NOT NULL,
