        (
            ("amount" IS NULL)
            OR ("currency_id" IS NOT NULL)
        )
    ),
    CONSTRAINT "chk_debts_identity_kind_enum" CHECK (
        "identity_kind" IN (
            'app',
            'bill',
            'coalition',
            'collection',
            'country',
            'currency',
            'debt',
            'election',
            'entity',
            'era',
            'event',
            'feature',
            'function',
            'fund',
            'hierarchy',
            'indicator',
            'individual',
            'instrument',
            'language',
            'level',
            'metric',
            'occurrence',
            'office',
            'pattern',
            'position',
            'procedure',
            'procurement',
            'product',
            'project',
            'service',
            'template',
            'timezone',
            'unit'
        )
    ),
    PRIMARY KEY ("id")
);

CREATE TABLE "finance"."findings" (
    "amount" bigint,
    "code" varchar(255) NOT NULL,
    "contract_id" uuid,
    "created_at" timestamptz NOT NULL,
    "currency_id" uuid,
    "deleted_at" timestamptz,
    "flow_country_id" uuid,
    "flow_id" uuid,
    "id" uuid NOT NULL,
    "institution_id" uuid NOT NULL,
    "kind_term" uuid NOT NULL,
    "period_id" uuid NOT NULL,
    "project_id" uuid,
    "status" text NOT NULL,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_findings_finding_amount_has_currency" CHECK (
        (
            ("amount" IS NULL)
            OR ("currency_id" IS NOT NULL)
        )
    ),
    CONSTRAINT "chk_findings_finding_flow_has_country" CHECK (
        (
            ("flow_id" IS NULL)
            OR ("flow_country_id" IS NOT NULL)
        )
    ),
    CONSTRAINT "chk_findings_status_enum" CHECK ("status" IN ('open', 'referred', 'resolved')),
    PRIMARY KEY ("id")
);

CREATE TABLE "finance"."flows" (
    "amount" bigint,
    "appropriation_id" uuid,
    "class_term" uuid,
    "contract_id" uuid,
    "counterparty_id" uuid,
    "country_id" uuid NOT NULL,
    "created_at" timestamptz NOT NULL,
    "currency_id" uuid,
    "debt_id" uuid,
    "deleted_at" timestamptz,
    "feature_id" uuid,
    "fund_id" uuid,
    "id" uuid NOT NULL,
    "institution_id" uuid,
    "kind" text NOT NULL,
    "occurred_on" date,
    "period_id" uuid,
    "project_id" uuid,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_flows_flow_amount_has_currency" CHECK (
        (
            ("amount" IS NULL)
            OR ("currency_id" IS NOT NULL)
        )
    ),
    CONSTRAINT "chk_flows_flow_has_an_anchor" CHECK (
        (
            ("fund_id" IS NOT NULL)
            OR ("appropriation_id" IS NOT NULL)
            OR ("contract_id" IS NOT NULL)
            OR ("debt_id" IS NOT NULL)
            OR ("project_id" IS NOT NULL)
            OR ("institution_id" IS NOT NULL)
        )
    ),
    CONSTRAINT "chk_flows_kind_enum" CHECK (
        "kind" IN (
            'allocation',
            'disbursement',
            'payment',
            'receipt',
            'transfer'
        )
    ),
    PRIMARY KEY ("id", "country_id")
)
PARTITION BY
    HASH ("country_id");

