    "identity_kind" text NOT NULL DEFAULT 'fund',
    "kind_term" uuid NOT NULL,
    "manager_id" uuid,
    "scope_id" uuid,
    "source_term" uuid,
    "template_id" uuid,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_funds_fund_kind" CHECK (("identity_kind" = 'fund')),
    CONSTRAINT "chk_funds_identity_kind_enum" CHECK (
        "identity_kind" IN (
            'app',
            'bill',
            'coalition',
            'collection',
            'country',
            'currency',
            'debt',
            'election',
            'entity',
            'era',
            'event',
            'feature',
            'function',
            'fund',
            'hierarchy',
            'indicator',
            'individual',
            'instrument',
            'language',
            'level',
            'metric',
            'occurrence',
            'office',
            'pattern',
            'position',
            'procedure',
            'procurement',
            'product',
            'project',
            'service',
            'template',
            'timezone',
            'unit'
        )
    ),
    PRIMARY KEY ("id")
);

CREATE TABLE "finance"."periods" (
    "code" varchar(255) NOT NULL,
    "country_id" uuid NOT NULL,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "ends_on" date NOT NULL,
    "from_year" integer,
    "id" uuid NOT NULL,
    "kind" text NOT NULL,
    "starts_on" date NOT NULL,
    "to_year" integer,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_periods_period_dates_are_ordered" CHECK (
        (
            ("starts_on" IS NULL)
            OR ("ends_on" IS NULL)
            OR ("starts_on" <= "ends_on")
        )
    ),
    CONSTRAINT "chk_periods_kind_enum" CHECK ("kind" IN ('fiscal-year', 'month', 'quarter')),
    PRIMARY KEY ("id")
);

CREATE TABLE "finance"."revisions" (
    "budget_id" uuid NOT NULL,
    "code" varchar(255) NOT NULL,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "id" uuid NOT NULL,
    "released_on" date,
    "revision" integer NOT NULL,
    "status" text NOT NULL,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_revisions_status_enum" CHECK ("status" IN ('approved', 'enacted', 'proposed')),
    PRIMARY KEY ("id")
);

CREATE TABLE "geography"."areas" (
    "code" varchar(255) NOT NULL,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "feature_id" uuid NOT NULL,
    "from_year" integer,
    "hierarchy_id" uuid NOT NULL,
    "id" uuid NOT NULL,
    "level_id" uuid NOT NULL,
    "parent_id" uuid,
    "template_id" uuid,
    "to_year" integer,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_areas_period_years_are_ordered" CHECK (
        (
            ("from_year" IS NULL)
            OR ("to_year" IS NULL)
            OR ("from_year" <= "to_year")
        )
    ),
    CONSTRAINT "chk_areas_area_is_not_its_own_parent" CHECK (("id" <> "parent_id")),
    PRIMARY KEY ("id")
);

CREATE TABLE "geography"."assets" (
    "band" integer,
    "built_at" timestamptz,
    "code" varchar(255) NOT NULL,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "feature_id" uuid NOT NULL,
    "geometry_id" uuid,
    "hierarchy_id" uuid,
    "id" uuid NOT NULL,
    "kind" text NOT NULL,
    "layer" varchar(255),
    "level_id" uuid,
    "member" varchar(1000),
    "purpose_term" uuid NOT NULL,
    "stale_at" timestamptz,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    "version_id" uuid NOT NULL,
    CONSTRAINT "chk_assets_kind_enum" CHECK (
        "kind" IN (
            'elevation',
            'outline',
            'raster',
            'thumbnail',
            'tile',
            'topojson',
            'vector-boundary'
        )
    ),
    PRIMARY KEY ("id")
);

CREATE TABLE "geography"."changes" (
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
