    "note_language_id" uuid,
    "occurrence_id" uuid,
    "predecessor_feature_id" uuid,
    "successor_feature_id" uuid,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_changes_change_has_a_place" CHECK (
        (
            ("predecessor_feature_id" IS NOT NULL)
            OR ("successor_feature_id" IS NOT NULL)
        )
    ),
    CONSTRAINT "chk_changes_change_note_has_language" CHECK (
        (
            ("note" IS NULL)
            OR ("note_language_id" IS NOT NULL)
        )
    ),
    CONSTRAINT "chk_changes_kind_enum" CHECK (
        "kind" IN ('merge', 'rename', 'split', 'transfer')
    ),
    PRIMARY KEY ("id")
);

CREATE TABLE "geography"."features" (
    "code" varchar(255) NOT NULL,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "ended_on" date,
    "established_on" date,
    "from_year" integer,
    "id" uuid NOT NULL,
    "identity_kind" text NOT NULL DEFAULT 'feature',
    "kind_term" uuid NOT NULL,
    "to_year" integer,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_features_feature_kind" CHECK (
        (
            ("identity_kind" = 'feature')
            OR ("identity_kind" = 'country')
        )
    ),
    CONSTRAINT "chk_features_feature_period_is_ordered" CHECK (
        (
            ("from_year" IS NULL)
            OR ("to_year" IS NULL)
            OR ("from_year" <= "to_year")
        )
    ),
    CONSTRAINT "chk_features_feature_dates_are_ordered" CHECK (
        (
            ("established_on" IS NULL)
            OR ("ended_on" IS NULL)
            OR ("established_on" <= "ended_on")
        )
    ),
    CONSTRAINT "chk_features_identity_kind_enum" CHECK (
        "identity_kind" IN (
            'app',
            'bill',
            'coalition',
            'collection',
            'country',
            'currency',
            'debt',
            'election',
            'entity',
            'era',
            'event',
            'feature',
            'function',
            'fund',
            'hierarchy',
            'indicator',
            'individual',
            'instrument',
            'language',
            'level',
            'metric',
            'occurrence',
            'office',
            'pattern',
            'position',
            'procedure',
            'procurement',
            'product',
            'project',
            'service',
            'template',
            'timezone',
            'unit'
        )
    ),
    PRIMARY KEY ("id")
);

CREATE TABLE "geography"."geometries" (
    "area" double precision GENERATED ALWAYS AS (ST_Area ("geometry")) STORED,
    "basis" text,
    "centroid" geometry (point, 4326) GENERATED ALWAYS AS (ST_Centroid ("geometry")) STORED,
    "confidence" double precision,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "envelope" geometry (geometry, 4326) GENERATED ALWAYS AS (ST_Envelope ("geometry")) STORED,
    "feature_id" uuid NOT NULL,
    "from_year" integer,
    "geometry" geometry (geometry, 4326),
    "id" uuid NOT NULL,
    "revision" integer NOT NULL,
    "role" text NOT NULL,
    "status" text NOT NULL DEFAULT 'established',
    "supersedes_id" uuid,
    "to_year" integer,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_geometries_geometry_is_not_its_own_successor" CHECK (("id" <> "supersedes_id")),
    CONSTRAINT "chk_geometries_basis_enum" CHECK (
        "basis" IN (
            'approximate',
            'derived',
            'digitised',
            'illustrative',
            'reconstructed',
            'surveyed',
            'traditional-claim'
        )
    ),
    CONSTRAINT "chk_geometries_role_enum" CHECK (
        "role" IN (
            'centreline',
            'centroid',
            'claimed-outline',
            'label-point',
            'outline',
            'point'
        )
    ),
    CONSTRAINT "chk_geometries_status_enum" CHECK ("status" IN ('draft', 'established', 'expected')),
    PRIMARY KEY ("id")
);

CREATE TABLE "geography"."outlines" (
    "band" integer NOT NULL,
    "bbox" geometry (polygon, 4326) NOT NULL,
    "built_at" timestamptz NOT NULL,
    "centroid" geometry (point, 4326) NOT NULL,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "feature_id" uuid NOT NULL,
    "geometry" geometry (geometry, 4326) NOT NULL,
    "geometry_id" uuid NOT NULL,
    "id" uuid NOT NULL,
    "points" integer NOT NULL,
    "tolerance" double precision NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "geography"."pieces" (
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "feature_id" uuid NOT NULL,
    "geometry" geometry (polygon, 4326) NOT NULL,
    "geometry_id" uuid NOT NULL,
    "id" uuid NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "geography"."relationships" (
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "ends_on" date,
    "from_year" integer,
    "id" uuid NOT NULL,
    "kind" text NOT NULL,
    "object_feature_id" uuid NOT NULL,
    "starts_on" date,
    "subject_feature_id" uuid NOT NULL,
    "to_year" integer,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_relationships_relationship_period_is_ordered" CHECK (
        (
            ("from_year" IS NULL)
            OR ("to_year" IS NULL)
            OR ("from_year" <= "to_year")
        )
    ),
    CONSTRAINT "chk_relationships_relationship_dates_are_ordered" CHECK (
        (
            ("starts_on" IS NULL)
            OR ("ends_on" IS NULL)
            OR ("starts_on" <= "ends_on")
        )
    ),
    CONSTRAINT "chk_relationships_relationship_is_not_self" CHECK (("subject_feature_id" <> "object_feature_id")),
    CONSTRAINT "chk_relationships_kind_enum" CHECK (
        "kind" IN (
            'borders',
            'connects',
            'flows-through',
            'inside',
            'located-on',
            'part-of',
            'replaced-by'
        )
    ),
    PRIMARY KEY ("id")
);

CREATE TABLE "governance"."appointments" (
    "actor_holder_id" uuid,
    "actor_id" uuid NOT NULL,
    "created_at" timestamptz NOT NULL,
