    "holder_id" uuid NOT NULL,
    "id" uuid NOT NULL,
    "motion_id" uuid,
    "on_date" date,
    "step" text NOT NULL,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_appointments_step_enum" CHECK (
        "step" IN (
            'appointment',
            'approval',
            'nomination',
            'recommendation',
            'swearing-in',
            'vetting'
        )
    ),
    PRIMARY KEY ("id")
);

CREATE TABLE "governance"."assignments" (
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "from_year" integer,
    "function_id" uuid NOT NULL,
    "id" uuid NOT NULL,
    "initiator_id" uuid,
    "institution_id" uuid,
    "position_id" uuid,
    "share" text NOT NULL,
    "to_year" integer,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_assignments_assignment_has_one_carrier" CHECK (
        (
            (
                ("institution_id" IS NOT NULL)
                AND ("position_id" IS NULL)
            )
            OR (
                ("institution_id" IS NULL)
                AND ("position_id" IS NOT NULL)
            )
