    CONSTRAINT "chk_names_name_period_is_ordered" CHECK (
        (
            ("from_year" IS NULL)
            OR ("to_year" IS NULL)
            OR ("from_year" <= "to_year")
        )
    ),
    CONSTRAINT "chk_names_identity_kind_enum" CHECK (
        "identity_kind" IN (
            'app',
            'bill',
            'coalition',
            'collection',
            'country',
            'currency',
            'debt',
            'election',
            'entity',
            'era',
            'event',
            'feature',
            'function',
            'fund',
            'hierarchy',
            'indicator',
            'individual',
            'instrument',
            'language',
            'level',
            'metric',
            'occurrence',
            'office',
            'pattern',
            'position',
            'procedure',
            'procurement',
            'product',
            'project',
            'service',
            'template',
            'timezone',
            'unit'
        )
    ),
    CONSTRAINT "chk_names_kind_enum" CHECK (
        "kind" IN (
            'abbreviation',
            'alternative',
            'definition',
            'historical',
            'local',
            'official',
            'preferred',
            'short',
            'transliteration'
        )
    ),
    PRIMARY KEY ("id", "identity_kind")
)
PARTITION BY
    LIST ("identity_kind");

CREATE TABLE "identity"."names_entity" PARTITION OF "identity"."names" FOR
VALUES
    IN ('entity');

CREATE TABLE "identity"."names_feature" PARTITION OF "identity"."names" FOR
VALUES
    IN ('feature');

CREATE TABLE "identity"."names_individual" PARTITION OF "identity"."names" FOR
VALUES
    IN ('individual');

CREATE TABLE "identity"."names_instrument" PARTITION OF "identity"."names" FOR
VALUES
    IN ('instrument');

CREATE TABLE "identity"."names_other" PARTITION OF "identity"."names" DEFAULT;

CREATE TABLE "identity"."names_reference" PARTITION OF "identity"."names" FOR
VALUES
    IN (
        'app',
        'country',
        'currency',
        'hierarchy',
        'language',
        'level',
        'timezone',
        'unit'
    );

CREATE TABLE "identity"."tags" (
