);

CREATE TABLE "legal"."editions" (
    "ceased_on" date,
    "code" varchar(255) NOT NULL,
    "commenced_on" date,
    "consolidated_on" date,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "designation" varchar(255) NOT NULL,
    "id" uuid NOT NULL,
    "instrument_id" uuid NOT NULL,
    "repealed_on" date,
    "supersedes_id" uuid,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "legal"."effects" (
    "code" varchar(255) NOT NULL,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "effective_on" date,
    "ended_on" date,
    "from_year" integer,
    "id" uuid NOT NULL,
    "identity_id" uuid NOT NULL,
    "kind_term" uuid NOT NULL,
    "note" varchar(4000),
    "note_language_id" uuid,
    "review_status" text NOT NULL,
    "to_year" integer,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    "wording_id" uuid NOT NULL,
    CONSTRAINT "chk_effects_effect_dates_are_ordered" CHECK (
        (
            ("effective_on" IS NULL)
            OR ("ended_on" IS NULL)
            OR ("effective_on" <= "ended_on")
        )
    ),
    CONSTRAINT "chk_effects_effect_note_has_language" CHECK (
        (
            ("note" IS NULL)
            OR ("note_language_id" IS NOT NULL)
        )
    ),
    CONSTRAINT "chk_effects_review_status_enum" CHECK (
        "review_status" IN ('accepted', 'proposed', 'rejected', 'reviewed')
    ),
    PRIMARY KEY ("id")
);

CREATE TABLE "legal"."instruments" (
