CREATE TABLE "legal"."provisions" (
    "code" varchar(255) NOT NULL,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "designation" varchar(255) NOT NULL,
    "id" uuid NOT NULL,
    "instrument_id" uuid NOT NULL,
    "kind" text NOT NULL,
    "parent_id" uuid,
    "position" integer NOT NULL,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_provisions_provision_is_not_its_own_parent" CHECK (("id" <> "parent_id")),
    CONSTRAINT "chk_provisions_kind_enum" CHECK (
        "kind" IN (
            'article',
            'chapter',
            'clause',
            'definition',
            'item',
            'paragraph',
            'part',
            'preamble',
            'schedule',
            'subparagraph'
        )
    ),
    PRIMARY KEY ("id")
);

CREATE TABLE "legal"."references" (
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "id" uuid NOT NULL,
    "metadata" jsonb,
    "method" text NOT NULL,
    "relation" text NOT NULL,
    "review_status" text NOT NULL,
    "span_end" integer NOT NULL,
    "span_start" integer NOT NULL,
    "span_text" varchar(500) NOT NULL,
    "target_provision_id" uuid NOT NULL,
    "target_wording_id" uuid,
    "translation_id" uuid,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    "wording_id" uuid,
    CONSTRAINT "chk_references_reference_has_one_source" CHECK (
        (
            (
                ("wording_id" IS NOT NULL)
                AND ("translation_id" IS NULL)
            )
            OR (
                ("wording_id" IS NULL)
                AND ("translation_id" IS NOT NULL)
            )
        )
    ),
    CONSTRAINT "chk_references_reference_span_is_ordered" CHECK (("span_start" < "span_end")),
    CONSTRAINT "chk_references_method_enum" CHECK ("method" IN ('human', 'model', 'parser')),
    CONSTRAINT "chk_references_relation_enum" CHECK (
        "relation" IN (
            'amends',
            'as-defined-in',
            'in-accordance-with',
            'read-with',
            'refers-to',
            'repeals',
            'subject-to',
            'under'
        )
    ),
    CONSTRAINT "chk_references_review_status_enum" CHECK (
        "review_status" IN ('accepted', 'proposed', 'rejected', 'reviewed')
    ),
    PRIMARY KEY ("id")
);

CREATE TABLE "legal"."relationships" (
    "affected_wording_id" uuid,
    "authority_wording_id" uuid,
    "code" varchar(255) NOT NULL,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "effective_on" date,
    "id" uuid NOT NULL,
    "kind_term" uuid NOT NULL,
    "note" varchar(4000),
    "note_language_id" uuid,
    "object_instrument_id" uuid,
    "resulting_wording_id" uuid,
    "subject_instrument_id" uuid,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_relationships_relationship_note_has_language" CHECK (
        (
            ("note" IS NULL)
            OR ("note_language_id" IS NOT NULL)
        )
    ),
    PRIMARY KEY ("id")
);

CREATE TABLE "legal"."translations" (
    "created_at" timestamptz NOT NULL,
