    "text" text NOT NULL,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    "wording_id" uuid NOT NULL,
    CONSTRAINT "chk_translations_method_enum" CHECK ("method" IN ('human', 'machine')),
    CONSTRAINT "chk_translations_review_enum" CHECK (
