    "language_id" uuid NOT NULL,
    "provision_id" uuid NOT NULL,
    "starts_on" date,
    "supersedes_id" uuid,
    "text" text NOT NULL,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
