    "motion_id" uuid,
    "position" integer NOT NULL,
    "sitting_id" uuid NOT NULL,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_agenda_agenda_has_at_most_one_item" CHECK (
        (
            (
                ("motion_id" IS NULL)
                AND ("bill_id" IS NULL)
            )
            OR (
                (
                    ("motion_id" IS NOT NULL)
                    AND ("bill_id" IS NULL)
                )
                OR (
                    ("motion_id" IS NULL)
                    AND ("bill_id" IS NOT NULL)
                )
            )
        )
    ),
    PRIMARY KEY ("id")
);

CREATE TABLE "legislature"."attachments" (
    "article_id" uuid,
    "asset_id" uuid,
    "bill_id" uuid,
    "country_id" uuid,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "end_second" double precision,
    "id" uuid NOT NULL,
    "position" integer,
    "purpose_term" uuid NOT NULL,
    "sitting_id" uuid,
    "speech_id" uuid,
    "start_second" double precision,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_attachments_attachment_has_one_row" CHECK (
        (
            (
                ("sitting_id" IS NOT NULL)
                AND ("bill_id" IS NULL)
                AND ("speech_id" IS NULL)
            )
            OR (
                ("sitting_id" IS NULL)
                AND ("bill_id" IS NOT NULL)
                AND ("speech_id" IS NULL)
            )
            OR (
                ("sitting_id" IS NULL)
                AND ("bill_id" IS NULL)
                AND ("speech_id" IS NOT NULL)
            )
        )
    ),
    CONSTRAINT "chk_attachments_attachment_has_one_media" CHECK (
        (
            (
                ("asset_id" IS NOT NULL)
                AND ("article_id" IS NULL)
            )
            OR (
                ("asset_id" IS NULL)
                AND ("article_id" IS NOT NULL)
            )
        )
    ),
    CONSTRAINT "chk_attachments_speech_attachment_has_country" CHECK (
        (
            ("speech_id" IS NULL)
            OR ("country_id" IS NOT NULL)
        )
    ),
    PRIMARY KEY ("id")
);

CREATE TABLE "legislature"."bills" (
    "code" varchar(255) NOT NULL,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "id" uuid NOT NULL,
    "identity_kind" text NOT NULL DEFAULT 'bill',
    "institution_id" uuid NOT NULL,
    "instrument_id" uuid,
    "kind_term" uuid NOT NULL,
    "sponsor_id" uuid,
    "status" text NOT NULL,
    "term_id" uuid,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_bills_bill_kind" CHECK (("identity_kind" = 'bill')),
    CONSTRAINT "chk_bills_identity_kind_enum" CHECK (
        "identity_kind" IN (
            'app',
            'bill',
            'coalition',
            'collection',
            'country',
            'currency',
            'debt',
            'election',
            'entity',
            'era',
            'event',
            'feature',
            'function',
            'fund',
            'hierarchy',
            'indicator',
            'individual',
            'instrument',
            'language',
            'level',
            'metric',
            'occurrence',
            'office',
            'pattern',
            'position',
            'procedure',
            'procurement',
            'product',
            'project',
            'service',
            'template',
            'timezone',
            'unit'
        )
    ),
    CONSTRAINT "chk_bills_status_enum" CHECK (
        "status" IN (
            'assented',
            'in-committee',
            'lapsed',
            'passed',
            'published',
            'withdrawn'
        )
