    "sitting_id" uuid NOT NULL,
    "status" text NOT NULL,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_hansards_status_enum" CHECK ("status" IN ('final', 'provisional')),
    PRIMARY KEY ("id")
);

CREATE TABLE "legislature"."motions" (
    "bill_id" uuid,
    "code" varchar(255) NOT NULL,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "id" uuid NOT NULL,
    "kind_term" uuid NOT NULL,
    "mover_id" uuid,
    "outcome" text,
    "period_id" uuid,
    "revision_id" uuid,
    "sitting_id" uuid NOT NULL,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_motions_motion_has_at_most_one_subject" CHECK (
        (
            (
                ("bill_id" IS NULL)
                AND ("revision_id" IS NULL)
                AND ("period_id" IS NULL)
            )
            OR (
                (
                    ("bill_id" IS NOT NULL)
                    AND ("revision_id" IS NULL)
                    AND ("period_id" IS NULL)
                )
                OR (
                    ("bill_id" IS NULL)
                    AND ("revision_id" IS NOT NULL)
                    AND ("period_id" IS NULL)
                )
                OR (
                    ("bill_id" IS NULL)
                    AND ("revision_id" IS NULL)
                    AND ("period_id" IS NOT NULL)
                )
            )
        )
    ),
    CONSTRAINT "chk_motions_outcome_enum" CHECK (
        "outcome" IN ('carried', 'negatived', 'withdrawn')
    ),
    PRIMARY KEY ("id")
);

CREATE TABLE "legislature"."sittings" (
