    "sitting_id" uuid,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_stages_outcome_enum" CHECK ("outcome" IN ('deferred', 'passed', 'rejected')),
