CREATE TABLE "legislature"."summaries" (
    "agenda_id" uuid,
    "bill_id" uuid,
    "country_id" uuid,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "id" uuid NOT NULL,
    "language_id" uuid NOT NULL,
    "motion_id" uuid,
    "origin" text NOT NULL,
    "speech_id" uuid,
    "status" text NOT NULL,
    "text" varchar(8000) NOT NULL,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_summaries_summary_has_one_subject" CHECK (
        (
            (
                ("bill_id" IS NOT NULL)
                AND ("motion_id" IS NULL)
                AND ("speech_id" IS NULL)
                AND ("agenda_id" IS NULL)
            )
            OR (
                ("bill_id" IS NULL)
                AND ("motion_id" IS NOT NULL)
                AND ("speech_id" IS NULL)
                AND ("agenda_id" IS NULL)
            )
            OR (
                ("bill_id" IS NULL)
                AND ("motion_id" IS NULL)
                AND ("speech_id" IS NOT NULL)
                AND ("agenda_id" IS NULL)
            )
            OR (
                ("bill_id" IS NULL)
                AND ("motion_id" IS NULL)
                AND ("speech_id" IS NULL)
                AND ("agenda_id" IS NOT NULL)
            )
        )
    ),
    CONSTRAINT "chk_summaries_speech_summary_has_country" CHECK (
        (
            ("speech_id" IS NULL)
            OR ("country_id" IS NOT NULL)
        )
    ),
    CONSTRAINT "chk_summaries_origin_enum" CHECK ("origin" IN ('human', 'machine', 'original')),
    CONSTRAINT "chk_summaries_status_enum" CHECK ("status" IN ('draft', 'published', 'reviewed')),
    PRIMARY KEY ("id")
);

