CREATE TABLE "media"."articles" (
    "author_id" uuid,
    "category_term" uuid NOT NULL,
    "code" varchar(255) NOT NULL,
    "contributor_id" uuid,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "id" uuid NOT NULL,
    "identity_id" uuid,
    "published_at" timestamptz,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "media"."assets" (
    "author" varchar(255),
    "availability" text,
    "captured_on" date,
    "checked_at" timestamptz,
    "code" varchar(255) NOT NULL,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "duration" double precision,
    "embed_url" varchar(2048),
    "end_second" double precision,
    "external_id" varchar(255),
    "external_url" varchar(2048),
    "height" integer,
    "id" uuid NOT NULL,
    "kind" text NOT NULL,
    "kind_term" uuid NOT NULL,
    "licence_term" uuid,
    "provider_term" uuid,
    "published_on" date,
    "start_second" double precision,
    "thumbnail_url" varchar(2048),
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    "version_id" uuid,
    "width" integer,
    CONSTRAINT "chk_assets_held_asset_has_bytes" CHECK (
        (
            ("kind" <> 'held')
            OR ("version_id" IS NOT NULL)
        )
    ),
    CONSTRAINT "chk_assets_external_asset_has_url" CHECK (
        (
            ("kind" = 'held')
            OR ("external_url" IS NOT NULL)
        )
    ),
    CONSTRAINT "chk_assets_asset_seconds_are_ordered" CHECK (
        (
            ("start_second" IS NULL)
            OR ("end_second" IS NULL)
            OR ("start_second" < "end_second")
        )
    ),
    CONSTRAINT "chk_assets_availability_enum" CHECK (
        "availability" IN ('live', 'removed', 'unavailable')
    ),
    CONSTRAINT "chk_assets_kind_enum" CHECK ("kind" IN ('embed', 'external', 'held')),
    PRIMARY KEY ("id")
);

CREATE TABLE "media"."captions" (
    "alt_text" varchar(1000),
    "asset_id" uuid NOT NULL,
