CREATE TABLE "politics"."attachments" (
    "article_id" uuid,
    "asset_id" uuid,
    "commitment_id" uuid,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "end_second" double precision,
    "fulfilment_id" uuid,
    "id" uuid NOT NULL,
    "manifesto_id" uuid,
    "position" integer,
    "purpose_term" uuid NOT NULL,
    "start_second" double precision,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_attachments_attachment_has_one_row" CHECK (
        (
            (
                ("commitment_id" IS NOT NULL)
                AND ("fulfilment_id" IS NULL)
                AND ("manifesto_id" IS NULL)
            )
            OR (
                ("commitment_id" IS NULL)
                AND ("fulfilment_id" IS NOT NULL)
                AND ("manifesto_id" IS NULL)
            )
            OR (
                ("commitment_id" IS NULL)
                AND ("fulfilment_id" IS NULL)
                AND ("manifesto_id" IS NOT NULL)
            )
        )
    ),
    CONSTRAINT "chk_attachments_attachment_has_one_media" CHECK (
        (
            (
                ("asset_id" IS NOT NULL)
                AND ("article_id" IS NULL)
            )
            OR (
                ("asset_id" IS NULL)
                AND ("article_id" IS NOT NULL)
            )
        )
    ),
    PRIMARY KEY ("id")
);

