            OR ("unit_id" IS NOT NULL)
        )
    ),
    CONSTRAINT "chk_commitments_speech_commitment_has_country" CHECK (
        (
            ("speech_id" IS NULL)
            OR ("country_id" IS NOT NULL)
        )
    ),
    CONSTRAINT "chk_commitments_kind_enum" CHECK (
        "kind" IN (
            'campaign-promise',
            'manifesto-pledge',
            'office-pledge'
        )
    ),
