CREATE TABLE "politics"."fulfilments" (
    "appropriation_id" uuid,
    "bill_id" uuid,
    "commitment_id" uuid NOT NULL,
    "contract_id" uuid,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "id" uuid NOT NULL,
    "instrument_id" uuid,
    "kind" text NOT NULL,
    "project_id" uuid,
    "recorded_on" date,
    "status" text NOT NULL,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_fulfilments_fulfilment_has_one_target" CHECK (
        (
            (
                ("project_id" IS NOT NULL)
                AND ("contract_id" IS NULL)
                AND ("appropriation_id" IS NULL)
                AND ("bill_id" IS NULL)
                AND ("instrument_id" IS NULL)
            )
            OR (
                ("project_id" IS NULL)
                AND ("contract_id" IS NOT NULL)
                AND ("appropriation_id" IS NULL)
                AND ("bill_id" IS NULL)
                AND ("instrument_id" IS NULL)
            )
            OR (
                ("project_id" IS NULL)
                AND ("contract_id" IS NULL)
                AND ("appropriation_id" IS NOT NULL)
                AND ("bill_id" IS NULL)
                AND ("instrument_id" IS NULL)
            )
            OR (
                ("project_id" IS NULL)
                AND ("contract_id" IS NULL)
                AND ("appropriation_id" IS NULL)
                AND ("bill_id" IS NOT NULL)
                AND ("instrument_id" IS NULL)
            )
            OR (
                ("project_id" IS NULL)
                AND ("contract_id" IS NULL)
                AND ("appropriation_id" IS NULL)
                AND ("bill_id" IS NULL)
                AND ("instrument_id" IS NOT NULL)
            )
        )
    ),
    CONSTRAINT "chk_fulfilments_kind_enum" CHECK (
        "kind" IN ('contradicts', 'delivers', 'partly-delivers')
    ),
    CONSTRAINT "chk_fulfilments_status_enum" CHECK ("status" IN ('claimed', 'disputed', 'verified')),
    PRIMARY KEY ("id")
);

