CREATE TABLE "source"."citations" (
    "artifact_id" uuid,
    "capture_id" uuid,
    "code" varchar(255) NOT NULL,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "id" uuid NOT NULL,
    "locator" varchar(4000) NOT NULL,
    "locator_term" uuid NOT NULL,
    "path_id" uuid,
    "quoted_hash" char(64),
    "recorded_at" timestamptz NOT NULL,
    "retrieved_at" timestamptz,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_citations_citation_has_one_origin" CHECK (
        (
            (
                ("artifact_id" IS NOT NULL)
                AND ("capture_id" IS NULL)
            )
            OR (
                ("artifact_id" IS NULL)
                AND ("capture_id" IS NOT NULL)
            )
        )
    ),
    PRIMARY KEY ("id")
);

CREATE TABLE "source"."contenders" (
    "claim" varchar(4000) NOT NULL,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "dispute_id" uuid NOT NULL,
    "evidence_id" uuid NOT NULL,
    "id" uuid NOT NULL,
    "is_preferred" boolean NOT NULL,
    "language_id" uuid NOT NULL,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "source"."coverage" (
    "checked_on" date,
    "code" varchar(255) NOT NULL,
    "country_id" uuid NOT NULL,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "expected_url" varchar(2048),
    "feature_id" uuid,
    "from_year" integer,
    "id" uuid NOT NULL,
    "level_id" uuid,
    "note" varchar(4000),
    "note_language_id" uuid,
    "product_id" uuid,
    "publisher_id" uuid,
    "source_id" uuid,
    "subject_term" uuid NOT NULL,
    "to_year" integer,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "source"."derivations" (
    "code" varchar(255) NOT NULL,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "id" uuid NOT NULL,
    "input_artifact_id" uuid,
    "input_edition_id" uuid,
    "input_version_id" uuid,
    "kind_term" uuid NOT NULL,
    "method" varchar(4000),
    "output_artifact_id" uuid,
    "output_edition_id" uuid,
    "output_version_id" uuid,
    "run" varchar(255),
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_derivations_derivation_has_one_output" CHECK (
        (
            (
                ("output_artifact_id" IS NOT NULL)
                AND ("output_edition_id" IS NULL)
                AND ("output_version_id" IS NULL)
            )
            OR (
                ("output_artifact_id" IS NULL)
                AND ("output_edition_id" IS NOT NULL)
                AND ("output_version_id" IS NULL)
            )
            OR (
                ("output_artifact_id" IS NULL)
                AND ("output_edition_id" IS NULL)
                AND ("output_version_id" IS NOT NULL)
            )
        )
    ),
    CONSTRAINT "chk_derivations_derivation_has_one_input" CHECK (
        (
            (
                ("input_artifact_id" IS NOT NULL)
                AND ("input_edition_id" IS NULL)
                AND ("input_version_id" IS NULL)
            )
            OR (
                ("input_artifact_id" IS NULL)
                AND ("input_edition_id" IS NOT NULL)
                AND ("input_version_id" IS NULL)
            )
            OR (
                ("input_artifact_id" IS NULL)
                AND ("input_edition_id" IS NULL)
                AND ("input_version_id" IS NOT NULL)
            )
        )
    ),
    PRIMARY KEY ("id")
);

CREATE TABLE "source"."discoveries" (
    "anchor_text" varchar(1000),
    "context" varchar(4000),
    "created_at" timestamptz NOT NULL,
    "discovered_at" timestamptz NOT NULL,
    "found_on_id" uuid,
    "id" uuid NOT NULL,
    "observed_url" varchar(2048) NOT NULL,
    "path_id" uuid,
    "source_id" uuid,
    PRIMARY KEY ("id", "discovered_at")
)
PARTITION BY
    RANGE ("discovered_at");

