CREATE TABLE "statistics"."figures" (
    "basis" text NOT NULL,
    "cell" varchar(1000) NOT NULL,
    "country_id" uuid NOT NULL,
    "created_at" timestamptz NOT NULL,
    "ends_on" date,
    "feature_id" uuid NOT NULL,
    "from_year" integer,
    "id" uuid NOT NULL,
    "indicator_id" uuid,
    "lower" double precision,
    "metric_id" uuid,
    "observation_id" uuid,
    "refreshed_at" timestamptz NOT NULL,
    "starts_on" date,
    "status" text NOT NULL,
    "subject_id" uuid,
    "to_year" integer,
    "upper" double precision,
    "value" double precision,
    CONSTRAINT "chk_figures_figure_has_one_measure" CHECK (
        (
            (
                ("indicator_id" IS NOT NULL)
                AND ("metric_id" IS NULL)
            )
            OR (
                ("indicator_id" IS NULL)
                AND ("metric_id" IS NOT NULL)
            )
        )
    ),
    CONSTRAINT "chk_figures_basis_enum" CHECK (
        "basis" IN (
            'aggregated',
            'estimated',
            'measured',
            'modelled',
            'projected'
        )
    ),
    CONSTRAINT "chk_figures_status_enum" CHECK (
        "status" IN (
            'estimated',
            'final',
            'missing',
            'projected',
            'provisional',
            'revised',
            'suppressed'
        )
    ),
    PRIMARY KEY ("id", "country_id")
)
PARTITION BY
    HASH ("country_id");

