CREATE TABLE "statistics"."observations" (
    "basis" text NOT NULL,
    "cell" varchar(1000) NOT NULL,
    "collection_id" uuid,
    "country_id" uuid NOT NULL,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "ends_on" date,
    "feature_id" uuid NOT NULL,
    "from_year" integer,
    "id" uuid NOT NULL,
    "indicator_id" uuid NOT NULL,
    "lower" double precision,
    "revision" integer NOT NULL,
    "starts_on" date,
    "status" text NOT NULL,
    "subject_id" uuid,
    "supersedes_id" uuid,
    "to_year" integer,
    "updated_at" timestamptz NOT NULL,
    "upper" double precision,
    "value" double precision,
    "version" integer NOT NULL,
    CONSTRAINT "chk_observations_observation_period_is_ordered" CHECK (
        (
            ("from_year" IS NULL)
            OR ("to_year" IS NULL)
            OR ("from_year" <= "to_year")
        )
    ),
    CONSTRAINT "chk_observations_bounds_are_ordered" CHECK (
        (
            ("lower" IS NULL)
            OR ("upper" IS NULL)
            OR ("lower" <= "upper")
        )
    ),
    CONSTRAINT "chk_observations_basis_enum" CHECK (
        "basis" IN (
            'aggregated',
            'estimated',
            'measured',
            'modelled',
            'projected'
        )
    ),
    CONSTRAINT "chk_observations_status_enum" CHECK (
        "status" IN (
            'estimated',
            'final',
            'missing',
            'projected',
            'provisional',
            'revised',
            'suppressed'
        )
    ),
    PRIMARY KEY ("id", "country_id")
)
PARTITION BY
    HASH ("country_id");

