CREATE TABLE "template"."templates" (
    "arm" text,
    "basis_term" uuid,
    "class_term" uuid,
    "code" varchar(255) NOT NULL,
    "confidence" double precision,
    "contact_kind" text,
    "contact_visibility" text,
    "contest_kind_term" uuid,
    "count_kind" text NOT NULL,
    "count_max" integer,
    "count_min" integer,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "election_kind_term" uuid,
    "election_past_status" text,
    "election_status" text,
    "entity_kind_term" uuid,
    "fan_out_level_id" uuid,
    "id" uuid NOT NULL,
    "identity_kind" text NOT NULL DEFAULT 'template',
    "kind_term" uuid,
    "method" text,
    "pattern_id" uuid NOT NULL,
    "premises_kind_term" uuid,
    "product" text NOT NULL,
    "reason" varchar(500),
    "repeat_years" integer,
    "role_term" uuid,
    "scope" text NOT NULL,
    "seat_count" integer,
    "sequence" integer NOT NULL DEFAULT 0,
    "start_year" integer,
    "term_kind_term" uuid,
    "term_limit" integer,
    "term_years" integer,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_templates_template_kind" CHECK (("identity_kind" = 'template')),
    CONSTRAINT "chk_templates_fan_out_needs_level" CHECK (
        (
            ("scope" = 'single')
            OR ("scope" = 'list')
            OR ("fan_out_level_id" IS NOT NULL)
        )
    ),
    CONSTRAINT "chk_templates_level_only_for_fan_out" CHECK (
        (
            ("scope" = 'level')
            OR ("scope" = 'within')
            OR ("fan_out_level_id" IS NULL)
        )
    ),
    CONSTRAINT "chk_templates_exact_count_needs_number" CHECK (
        (
            ("count_kind" <> 'exact')
            OR ("count_min" IS NOT NULL)
        )
    ),
    CONSTRAINT "chk_templates_minimum_count_needs_number" CHECK (
        (
            ("count_kind" <> 'minimum')
            OR ("count_min" IS NOT NULL)
        )
    ),
    CONSTRAINT "chk_templates_maximum_count_needs_number" CHECK (
        (
            ("count_kind" <> 'maximum')
            OR ("count_max" IS NOT NULL)
        )
    ),
    CONSTRAINT "chk_templates_range_count_needs_bounds" CHECK (
        (
            ("count_kind" <> 'range')
            OR (
                ("count_min" IS NOT NULL)
                AND ("count_max" IS NOT NULL)
            )
        )
    ),
    CONSTRAINT "chk_templates_count_bounds_are_ordered" CHECK (
        (
            ("count_min" IS NULL)
            OR ("count_max" IS NULL)
            OR ("count_min" <= "count_max")
        )
    ),
    CONSTRAINT "chk_templates_institution_attributes_need_institution" CHECK (
        (
            ("product" = 'institution')
            OR (
                ("kind_term" IS NULL)
                AND ("arm" IS NULL)
                AND ("class_term" IS NULL)
            )
        )
    ),
    CONSTRAINT "chk_templates_position_attributes_need_seat" CHECK (
        (
            ("product" = 'position')
            OR ("product" = 'office')
            OR ("product" = 'term')
            OR ("product" = 'holder')
            OR (
                ("role_term" IS NULL)
                AND ("method" IS NULL)
                AND ("basis_term" IS NULL)
                AND ("seat_count" IS NULL)
                AND ("term_years" IS NULL)
                AND ("term_limit" IS NULL)
            )
        )
    ),
    CONSTRAINT "chk_templates_premises_kind_needs_premises" CHECK (
        (
            ("product" = 'premises')
            OR ("premises_kind_term" IS NULL)
        )
    ),
    CONSTRAINT "chk_templates_contact_kind_needs_contact" CHECK (
        (
            ("product" = 'contact')
            OR ("contact_kind" IS NULL)
        )
    ),
    CONSTRAINT "chk_templates_repeat_needs_repeating_product" CHECK (
        (
            ("repeat_years" IS NULL)
            OR ("product" = 'election-cycle')
            OR ("product" = 'term')
            OR ("product" = 'event-schedule')
        )
    ),
    CONSTRAINT "chk_templates_arm_enum" CHECK (
        "arm" IN (
            'county',
            'devolved-government',
            'executive',
            'funds',
            'independent',
            'independent-commission',
            'judiciary',
            'legislature'
        )
    ),
    CONSTRAINT "chk_templates_contact_kind_enum" CHECK (
        "contact_kind" IN (
            'email',
            'facebook',
            'fax',
            'instagram',
            'landmark',
            'mobile',
            'physical-address',
            'postal-address',
            'social-media',
            'telephone',
            'tiktok',
            'website',
            'x',
            'youtube'
        )
    ),
    CONSTRAINT "chk_templates_contact_visibility_enum" CHECK (
        "contact_visibility" IN ('private', 'public', 'restricted')
    ),
    CONSTRAINT "chk_templates_count_kind_enum" CHECK (
        "count_kind" IN ('exact', 'maximum', 'minimum', 'range')
    ),
    CONSTRAINT "chk_templates_election_past_status_enum" CHECK (
        "election_past_status" IN ('annulled', 'held', 'scheduled')
    ),
    CONSTRAINT "chk_templates_election_status_enum" CHECK (
        "election_status" IN ('annulled', 'held', 'scheduled')
    ),
    CONSTRAINT "chk_templates_identity_kind_enum" CHECK (
        "identity_kind" IN (
            'app',
            'bill',
            'coalition',
            'collection',
            'country',
            'currency',
            'debt',
            'election',
            'entity',
            'era',
            'event',
            'feature',
            'function',
            'fund',
            'hierarchy',
            'indicator',
            'individual',
            'instrument',
            'language',
            'level',
            'metric',
            'occurrence',
            'office',
            'pattern',
            'position',
            'procedure',
            'procurement',
            'product',
            'project',
            'service',
            'template',
            'timezone',
            'unit'
        )
    ),
    CONSTRAINT "chk_templates_method_enum" CHECK (
        "method" IN (
            'acting',
            'appointed',
            'elected',
            'elected-by-members',
            'ex-officio',
            'nominated',
            'running-mate'
        )
    ),
    CONSTRAINT "chk_templates_product_enum" CHECK (
        "product" IN (
            'area',
            'budget',
            'contact',
            'contest',
            'domain',
            'election-cycle',
            'event-rule',
            'event-schedule',
            'fund',
            'holder',
            'institution',
            'office',
            'position',
            'premises',
            'term'
        )
    ),
    CONSTRAINT "chk_templates_scope_enum" CHECK ("scope" IN ('level', 'list', 'single', 'within')),
    PRIMARY KEY ("id")
);

CREATE TABLE "template"."texts" (
    "body" varchar(1000) NOT NULL,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "id" uuid NOT NULL,
    "language_id" uuid,
    "name_kind" text,
    "purpose" text NOT NULL,
    "template_id" uuid NOT NULL,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_texts_name_has_language" CHECK (
        (
            ("purpose" <> 'name')
            OR ("language_id" IS NOT NULL)
        )
    ),
    CONSTRAINT "chk_texts_name_has_kind" CHECK (
        (
            ("purpose" <> 'name')
            OR ("name_kind" IS NOT NULL)
        )
    ),
    CONSTRAINT "chk_texts_only_names_have_language" CHECK (
        (
            ("purpose" = 'name')
            OR ("language_id" IS NULL)
        )
    ),
    CONSTRAINT "chk_texts_name_kind_enum" CHECK (
        "name_kind" IN (
            'abbreviation',
            'alternative',
            'definition',
            'historical',
            'local',
            'official',
            'preferred',
            'short',
            'transliteration'
        )
    ),
    CONSTRAINT "chk_texts_purpose_enum" CHECK (
        "purpose" IN ('code', 'contact', 'domain', 'name')
    ),
    PRIMARY KEY ("id")
);

CREATE TABLE "vocabulary"."labels" (
    "country_id" uuid,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "id" uuid NOT NULL,
    "kind" text NOT NULL,
    "language_id" uuid NOT NULL,
    "scheme_id" uuid,
    "term_id" uuid,
    "text" varchar(1000) NOT NULL,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_labels_labels_one_owner" CHECK (
        (
            (
                ("term_id" IS NOT NULL)
                AND ("scheme_id" IS NULL)
            )
            OR (
                ("term_id" IS NULL)
                AND ("scheme_id" IS NOT NULL)
            )
        )
    ),
    CONSTRAINT "chk_labels_kind_enum" CHECK (
        "kind" IN (
            'abbreviation',
            'alternative',
            'definition',
            'plural',
            'preferred',
            'short'
        )
    ),
    PRIMARY KEY ("id")
);

CREATE TABLE "vocabulary"."mappings" (
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "from_id" uuid NOT NULL,
    "id" uuid NOT NULL,
    "kind" text NOT NULL,
    "to_id" uuid NOT NULL,
    CONSTRAINT "chk_mappings_mapping_is_not_itself" CHECK (("from_id" <> "to_id")),
    CONSTRAINT "chk_mappings_kind_enum" CHECK (
        "kind" IN (
            'broader',
            'close',
            'exact',
            'narrower',
            'related'
        )
    ),
    PRIMARY KEY ("id")
);

CREATE TABLE "vocabulary"."schemes" (
    "answers" text NOT NULL,
    "code" varchar(255) NOT NULL,
    "country_id" uuid,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "id" uuid NOT NULL,
    "is_dated" boolean NOT NULL,
    "is_open" boolean NOT NULL,
    "shape" text NOT NULL,
    "steward_id" uuid,
    "updated_at" timestamptz NOT NULL,
    "version" integer NOT NULL,
    CONSTRAINT "chk_schemes_answers_enum" CHECK ("answers" IN ('many', 'one')),
    CONSTRAINT "chk_schemes_shape_enum" CHECK ("shape" IN ('flat', 'graph', 'tree')),
    PRIMARY KEY ("id")
);

CREATE TABLE "vocabulary"."scopes" (
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "id" uuid NOT NULL,
    "identity_kind" text NOT NULL,
    "scheme_id" uuid NOT NULL,
    CONSTRAINT "chk_scopes_identity_kind_enum" CHECK (
        "identity_kind" IN (
            'app',
            'bill',
            'coalition',
            'collection',
            'country',
            'currency',
            'debt',
            'election',
            'entity',
            'era',
            'event',
            'feature',
            'function',
            'fund',
            'hierarchy',
            'indicator',
            'individual',
            'instrument',
            'language',
            'level',
            'metric',
            'occurrence',
            'office',
            'pattern',
            'position',
            'procedure',
            'procurement',
            'product',
            'project',
            'service',
            'template',
            'timezone',
            'unit'
        )
    ),
    PRIMARY KEY ("id")
);

CREATE TABLE "vocabulary"."terms" (
    "code" varchar(255) NOT NULL,
    "color_token" varchar(100),
    "country_id" uuid,
    "created_at" timestamptz NOT NULL,
    "deleted_at" timestamptz,
    "icon_code" varchar(100),
    "id" uuid NOT NULL,
    "lower" double precision,
    "lower_inclusive" boolean,
    "parent_id" uuid,
    "position" integer,
    "scheme_id" uuid NOT NULL,
    "status" text NOT NULL,
    "supersedes_id" uuid,
    "unit_id" uuid,
    "updated_at" timestamptz NOT NULL,
    "upper" double precision,
    "upper_inclusive" boolean,
    "version" integer NOT NULL,
    CONSTRAINT "chk_terms_term_is_not_its_own_parent" CHECK (("parent_id" <> "id")),
    CONSTRAINT "chk_terms_band_has_unit" CHECK (
        (
            (
                ("lower" IS NULL)
                AND ("upper" IS NULL)
            )
            OR ("unit_id" IS NOT NULL)
        )
    ),
    CONSTRAINT "chk_terms_band_is_ordered" CHECK (
        (
            ("lower" IS NULL)
            OR ("upper" IS NULL)
            OR ("lower" <= "upper")
        )
    ),
    CONSTRAINT "chk_terms_status_enum" CHECK ("status" IN ('active', 'deprecated', 'retired')),
    PRIMARY KEY ("id")
);

