CREATE FUNCTION "vocabulary"."terms__term_parents_have_no_cycle" () RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
  IF NEW."parent_id" IS NOT NULL AND EXISTS (
    WITH RECURSIVE chain(id) AS (
      SELECT NEW."parent_id"
      UNION
      SELECT t."parent_id" FROM "vocabulary"."terms" t JOIN chain ON t."id" = chain.id WHERE t."parent_id" IS NOT NULL
    ) SELECT 1 FROM chain WHERE id = NEW."id"
  ) THEN
    RAISE EXCEPTION 'terms.parent_id would create a cycle' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END
$fn$;

CREATE TRIGGER "tr_terms__term_parents_have_no_cycle"
BEFORE INSERT OR UPDATE OF "parent_id" ON "vocabulary"."terms" FOR EACH ROW
EXECUTE FUNCTION "vocabulary"."terms__term_parents_have_no_cycle" ();

