CREATE FUNCTION "civic"."scheme_attachments_purpose_term" () RETURNS trigger LANGUAGE plpgsql AS $scheme$
BEGIN
  IF NEW."purpose_term" IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM "vocabulary"."terms" v
    JOIN "vocabulary"."schemes" s ON s."id" = v."scheme_id"
    WHERE v."id" = NEW."purpose_term" AND s."code" = 'voc.sch.med.attachment.purpose'
    FOR SHARE OF v, s
  ) THEN
    RAISE EXCEPTION 'referenced value belongs to a different scheme' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$scheme$;

CREATE TRIGGER "scheme_attachments_purpose_term"
BEFORE INSERT OR UPDATE OF "purpose_term" ON "civic"."attachments" FOR EACH ROW
EXECUTE FUNCTION "civic"."scheme_attachments_purpose_term" ();

CREATE FUNCTION "civic"."scheme_attachments_purpose_term_membership" () RETURNS trigger LANGUAGE plpgsql AS $scheme$
BEGIN
  IF NEW."scheme_id" IS DISTINCT FROM OLD."scheme_id" AND EXISTS (
    SELECT 1 FROM "civic"."attachments" t WHERE t."purpose_term" = OLD."id"
  ) THEN
    RAISE EXCEPTION 'cannot move a value used by a scheme-constrained link' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$scheme$;

