  IF OLD."code" = 'voc.sch.fil.folder.role' AND NEW."code" IS DISTINCT FROM OLD."code" AND EXISTS (
    SELECT 1 FROM "filesystem"."folders" t
    JOIN "vocabulary"."terms" v ON v."id" = t."role_term"
