CREATE FUNCTION "politics"."scheme_parties_kind_term_code" () RETURNS trigger LANGUAGE plpgsql AS $scheme$
BEGIN
  IF OLD."code" = 'voc.sch.pol.party.kind' AND NEW."code" IS DISTINCT FROM OLD."code" AND EXISTS (
    SELECT 1 FROM "politics"."parties" t
    JOIN "vocabulary"."terms" v ON v."id" = t."kind_term"
    WHERE v."scheme_id" = OLD."id"
  ) THEN
    RAISE EXCEPTION 'cannot rename a scheme used by a scheme-constrained link' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$scheme$;

