COMMENT ON TABLE "auth"."accounts" IS E'A sign-in principal for a person, service or agent.';

COMMENT ON COLUMN "auth"."accounts"."actor_kind" IS E'person, service or agent.';

COMMENT ON COLUMN "auth"."accounts"."individual_id" IS E'Set only when the account belongs to a known public person.';

COMMENT ON TABLE "auth"."allowances" IS E'The security ceiling of a delegation: the roles a delegate may receive through it.';

COMMENT ON TABLE "auth"."codes" IS E'A one-time sign-up or sign-in code.';

COMMENT ON COLUMN "auth"."codes"."attempts" IS E'Failed attempts so far; limited, for example 5.';

COMMENT ON COLUMN "auth"."codes"."consumed_at" IS E'When the code was used; codes are single use.';

COMMENT ON COLUMN "auth"."codes"."digest" IS E'Hash of the code; the code itself is never stored.';

COMMENT ON COLUMN "auth"."codes"."expires_at" IS E'Short expiry, for example 10 minutes.';

COMMENT ON COLUMN "auth"."codes"."login_id" IS E'The login the code verifies; empty for a new sign-up.';

COMMENT ON COLUMN "auth"."codes"."purpose" IS E'signup, signin or change.';

COMMENT ON COLUMN "auth"."codes"."value" IS E'The email or phone being verified for a new sign-up.';

COMMENT ON TABLE "auth"."delegations" IS E'Time-limited delegation of scoped access from one account to another.';

COMMENT ON TABLE "auth"."grants" IS E'Who holds which role, within which scope, with revocation history.';

COMMENT ON COLUMN "auth"."grants"."delegation_id" IS E'The delegation the grant came from.';

COMMENT ON TABLE "auth"."invitations" IS E'A single-use invitation to an institution.';

COMMENT ON COLUMN "auth"."invitations"."token_digest" IS E'Hash of the invitation token; the token is never stored.';

COMMENT ON TABLE "auth"."logins" IS E'A way an account signs in: email or phone with one-time codes, or an OIDC issuer and subject.';

COMMENT ON COLUMN "auth"."logins"."issuer" IS E'OIDC issuer.';

COMMENT ON COLUMN "auth"."logins"."kind" IS E'email, phone or oidc.';

COMMENT ON COLUMN "auth"."logins"."subject" IS E'OIDC subject.';

COMMENT ON COLUMN "auth"."logins"."value" IS E'Email stored lowercase or phone in E.164 (+254712345678); empty for OIDC.';

COMMENT ON TABLE "auth"."memberships" IS E'An account''s membership of an institution, verified and revocable with attribution.';

COMMENT ON TABLE "auth"."permissions" IS E'A named action on a resource type, optionally narrowed to a field group.';

COMMENT ON COLUMN "auth"."permissions"."code" IS E'Stable row code (`.docs/rules/codes.md`): lowercase, dot-separated, unique and never reused.';

COMMENT ON COLUMN "auth"."permissions"."field_group" IS E'Optional group of fields the permission narrows to.';

COMMENT ON COLUMN "auth"."permissions"."resource_type" IS E'The schema whose data the permission covers.';

COMMENT ON TABLE "auth"."privileges" IS E'What a role may do: a permission granted to a role, with who granted it and when.';

COMMENT ON TABLE "auth"."roles" IS E'A named permission bundle with a policy version.';

COMMENT ON COLUMN "auth"."roles"."code" IS E'Stable row code (`.docs/rules/codes.md`): lowercase, dot-separated, unique and never reused.';

COMMENT ON COLUMN "auth"."roles"."institution_id" IS E'The institution that manages the role.';

COMMENT ON COLUMN "auth"."roles"."protected" IS E'True when the role cannot be edited away.';

COMMENT ON COLUMN "auth"."roles"."title" IS E'Internal English title for administrators.';

COMMENT ON TABLE "auth"."scopes" IS E'A deduplicated access scope: global, or narrowed by institution, country, place or field group.';

COMMENT ON COLUMN "auth"."scopes"."include_descendants" IS E'True when the scope covers places under `feature_id`.';

COMMENT ON COLUMN "auth"."scopes"."scope_hash" IS E'Hash of the scope''s columns, so equal scopes are one row.';

