COMMENT ON COLUMN "geography"."assets"."built_at" IS E'When a prepared output was built.';

COMMENT ON COLUMN "geography"."assets"."code" IS E'Stable row code (`.docs/rules/codes.md`): lowercase, dot-separated, unique and never reused.';

COMMENT ON COLUMN "geography"."assets"."deleted_at" IS E'Soft-delete time; empty while the record is live.';

COMMENT ON COLUMN "geography"."assets"."geometry_id" IS E'Set when the file is the drawing of one geometry.';

COMMENT ON COLUMN "geography"."assets"."hierarchy_id" IS E'For a prepared output: the hierarchy it draws.';

COMMENT ON COLUMN "geography"."assets"."kind" IS E'vector boundary, raster, elevation, tile set, TopoJSON.';

COMMENT ON COLUMN "geography"."assets"."layer" IS E'Layer name in a multi-layer file.';

COMMENT ON COLUMN "geography"."assets"."level_id" IS E'For a prepared output: the level it draws.';

COMMENT ON COLUMN "geography"."assets"."member" IS E'Member path inside an archive.';

COMMENT ON COLUMN "geography"."assets"."purpose_term" IS E'boundary source, elevation, land cover, prepared map output. Term from vocabulary scheme `geo.asset.purpose`.';

COMMENT ON COLUMN "geography"."assets"."stale_at" IS E'When a source geometry changed after the build; a stale output is rebuilt.';

COMMENT ON COLUMN "geography"."assets"."version" IS E'Optimistic-concurrency version; starts at 1 and increases on every update.';

COMMENT ON COLUMN "geography"."assets"."version_id" IS E'The exact stored GIS file, tile set or TopoJSON.';

COMMENT ON TABLE "geography"."changes" IS E'One edge of a boundary change: splits, merges, creation or dissolution, without overwriting the places.';

COMMENT ON COLUMN "geography"."changes"."deleted_at" IS E'Soft-delete time; empty while the record is live.';

COMMENT ON COLUMN "geography"."changes"."kind" IS E'split, merge, rename or transfer.';

COMMENT ON COLUMN "geography"."changes"."note" IS E'Optional explanation, in `note_language_id`.';

COMMENT ON COLUMN "geography"."changes"."occurrence_id" IS E'The historical reform behind the change (Kenya''s 2013 devolution).';

COMMENT ON COLUMN "geography"."changes"."version" IS E'Optimistic-concurrency version; starts at 1 and increases on every update.';

COMMENT ON TABLE "geography"."features" IS E'The one identity of every place, natural or administrative. A country''s feature shares the country''s identity; parents and ranks are dated relationships, never columns here.';

