COMMENT ON COLUMN "geography"."features"."established_on" IS E'Exact date the place came into being.';

COMMENT ON COLUMN "geography"."features"."from_year" IS E'First year of the period (negative for BCE); empty when the start is not known.';

COMMENT ON COLUMN "geography"."features"."id" IS E'The identity this row extends: the same uuid as `identity.identities.id`.';

