COMMENT ON COLUMN "geography"."relationships"."to_year" IS E'Last year of the period; empty while the period has not ended.';

COMMENT ON COLUMN "geography"."relationships"."version" IS E'Optimistic-concurrency version; starts at 1 and increases on every update.';

