COMMENT ON COLUMN "statistics"."collections"."steward_id" IS E'The producer (KNBS, NBS, the World Bank, IEBC).';

COMMENT ON COLUMN "statistics"."collections"."to_year" IS E'Last year of the period; empty while the period has not ended.';

COMMENT ON COLUMN "statistics"."collections"."version" IS E'Optimistic-concurrency version; starts at 1 and increases on every update.';

COMMENT ON TABLE "statistics"."components" IS E'One part of a composite index, with its weight and transform.';

COMMENT ON COLUMN "statistics"."components"."component_id" IS E'One indicator it is made from.';

COMMENT ON COLUMN "statistics"."components"."indicator_id" IS E'The composite index.';

COMMENT ON COLUMN "statistics"."components"."transform" IS E'as is, normalised, inverted.';

COMMENT ON TABLE "statistics"."dimensions" IS E'Which breakdowns an indicator allows, in order.';

COMMENT ON COLUMN "statistics"."dimensions"."scheme_id" IS E'The breakdown scheme (sex, age group, residence).';

COMMENT ON TABLE "statistics"."figures" IS E'Prepared: the one value to show per indicator or metric, place, subject, period and cell; refreshed after every load.';

COMMENT ON COLUMN "statistics"."figures"."cell" IS E'Fingerprint of the sorted breakdown term codes; the empty string is the total.';

COMMENT ON COLUMN "statistics"."figures"."country_id" IS E'Partition key; every read filters by it first.';

COMMENT ON COLUMN "statistics"."figures"."feature_id" IS E'The place the figure describes.';

COMMENT ON COLUMN "statistics"."figures"."from_year" IS E'First year of the period (negative for BCE); empty when the start is not known.';

COMMENT ON COLUMN "statistics"."figures"."indicator_id" IS E'The indicator measured; exactly one of indicator and metric on figures.';

COMMENT ON COLUMN "statistics"."figures"."lower" IS E'Lower bound of the uncertainty interval.';

COMMENT ON COLUMN "statistics"."figures"."observation_id" IS E'The observation chosen; empty for a computed metric.';

COMMENT ON COLUMN "statistics"."figures"."subject_id" IS E'A thing the figure is about (the Swahili language for speakers of Swahili).';

COMMENT ON COLUMN "statistics"."figures"."to_year" IS E'Last year of the period; empty while the period has not ended.';

COMMENT ON COLUMN "statistics"."figures"."upper" IS E'Upper bound of the uncertainty interval.';

COMMENT ON COLUMN "statistics"."figures"."value" IS E'In the indicator''s base unit; empty when missing or suppressed.';

COMMENT ON TABLE "statistics"."indicators" IS E'The concept measured (Population). Its names and short definitions are `identity.names`.';

COMMENT ON COLUMN "statistics"."indicators"."aggregation" IS E'How lower levels may build a total; rates are never summed.';

COMMENT ON COLUMN "statistics"."indicators"."code" IS E'Stable row code (`.docs/rules/codes.md`): lowercase, dot-separated, unique and never reused.';

COMMENT ON COLUMN "statistics"."indicators"."decimals" IS E'Decimals to show.';

COMMENT ON COLUMN "statistics"."indicators"."deleted_at" IS E'Soft-delete time; empty while the record is live.';

COMMENT ON COLUMN "statistics"."indicators"."id" IS E'The identity this row extends: the same uuid as `identity.identities.id`.';

COMMENT ON COLUMN "statistics"."indicators"."identity_kind" IS E'Kind of the identity this row extends; with `id` it is a composite foreign key to `identity.identities (id, kind)`.';

COMMENT ON COLUMN "statistics"."indicators"."is_derived" IS E'True when computed from components.';

COMMENT ON COLUMN "statistics"."indicators"."kind" IS E'count, rate, ratio, index, share.';

COMMENT ON COLUMN "statistics"."indicators"."role_term" IS E'The part it plays on screens (population, density, area). Term from vocabulary scheme `sta.indicator.role`.';

COMMENT ON COLUMN "statistics"."indicators"."topic_term" IS E'The topic (Demographics). Term from vocabulary scheme `topic`.';

COMMENT ON COLUMN "statistics"."indicators"."version" IS E'Optimistic-concurrency version; starts at 1 and increases on every update.';

COMMENT ON TABLE "statistics"."metrics" IS E'A figure calculated from indicators (a rate per 1,000); computed when `figures` is refreshed.';

COMMENT ON COLUMN "statistics"."metrics"."code" IS E'Stable row code (`.docs/rules/codes.md`): lowercase, dot-separated, unique and never reused.';

COMMENT ON COLUMN "statistics"."metrics"."deleted_at" IS E'Soft-delete time; empty while the record is live.';

COMMENT ON COLUMN "statistics"."metrics"."id" IS E'The identity this row extends: the same uuid as `identity.identities.id`.';

COMMENT ON COLUMN "statistics"."metrics"."identity_kind" IS E'Kind of the identity this row extends; with `id` it is a composite foreign key to `identity.identities (id, kind)`.';

COMMENT ON COLUMN "statistics"."metrics"."level_term" IS E'The level shown first. Term from vocabulary scheme `geo.level.kind`.';

COMMENT ON COLUMN "statistics"."metrics"."per_factor" IS E'Factor after dividing (1000 for per 1,000 people).';

COMMENT ON COLUMN "statistics"."metrics"."topic_term" IS E'The topic. Term from vocabulary scheme `topic`.';

COMMENT ON COLUMN "statistics"."metrics"."version" IS E'Optimistic-concurrency version; starts at 1 and increases on every update.';

COMMENT ON TABLE "statistics"."observations" IS E'One published figure for an indicator, place, subject, period and breakdown cell, by collection and revision.';

COMMENT ON COLUMN "statistics"."observations"."cell" IS E'Fingerprint of the sorted breakdown term codes; the empty string is the total.';

COMMENT ON COLUMN "statistics"."observations"."country_id" IS E'Partition key; every read filters by it first.';

COMMENT ON COLUMN "statistics"."observations"."deleted_at" IS E'Soft-delete time; empty while the record is live.';

COMMENT ON COLUMN "statistics"."observations"."feature_id" IS E'The place the figure describes.';

COMMENT ON COLUMN "statistics"."observations"."from_year" IS E'First year of the period (negative for BCE); empty when the start is not known.';

COMMENT ON COLUMN "statistics"."observations"."lower" IS E'Lower bound of the uncertainty interval.';

COMMENT ON COLUMN "statistics"."observations"."revision" IS E'1 first; a correction is a new row with a higher revision.';

COMMENT ON COLUMN "statistics"."observations"."subject_id" IS E'A thing the figure is about (the Swahili language for speakers of Swahili).';

COMMENT ON COLUMN "statistics"."observations"."supersedes_id" IS E'The earlier figure this revision replaces.';

COMMENT ON COLUMN "statistics"."observations"."to_year" IS E'Last year of the period; empty while the period has not ended.';

COMMENT ON COLUMN "statistics"."observations"."upper" IS E'Upper bound of the uncertainty interval.';

COMMENT ON COLUMN "statistics"."observations"."value" IS E'In the indicator''s base unit; empty when missing or suppressed.';

COMMENT ON COLUMN "statistics"."observations"."version" IS E'Optimistic-concurrency version; starts at 1 and increases on every update.';

COMMENT ON TABLE "statistics"."priorities" IS E'Per-country order of trust for choosing the figure to show (Kenya ranks KNBS first).';

COMMENT ON COLUMN "statistics"."priorities"."deleted_at" IS E'Soft-delete time; empty while the record is live.';

COMMENT ON COLUMN "statistics"."priorities"."position" IS E'Rank; 0 is trusted first.';

COMMENT ON COLUMN "statistics"."priorities"."steward_id" IS E'A producer ranked for this country.';

COMMENT ON COLUMN "statistics"."priorities"."version" IS E'Optimistic-concurrency version; starts at 1 and increases on every update.';

COMMENT ON TABLE "template"."items" IS E'One fixed list entry of a template with the list scope (the Article 250 commissions, the cabinet portfolios).';

COMMENT ON COLUMN "template"."items"."code" IS E'Stable row code (`.docs/rules/codes.md`): lowercase, dot-separated, unique and never reused.';

COMMENT ON COLUMN "template"."items"."deleted_at" IS E'Soft-delete time; empty while the record is live.';

COMMENT ON COLUMN "template"."items"."key" IS E'Short token used in the template''s texts (`iebc`).';

COMMENT ON COLUMN "template"."items"."name" IS E'The item''s name in `language_id`.';

COMMENT ON COLUMN "template"."items"."version" IS E'Optimistic-concurrency version; starts at 1 and increases on every update.';

COMMENT ON TABLE "template"."lines" IS E'One effect line: when the first template creates a row, the second runs for it. This list is how a template records its effects; the effects themselves carry no template column.';

COMMENT ON COLUMN "template"."lines"."deleted_at" IS E'Soft-delete time; empty while the record is live.';

COMMENT ON COLUMN "template"."lines"."effect_template_id" IS E'The template that runs for every row the first one creates.';

COMMENT ON COLUMN "template"."lines"."position" IS E'Order in which effects run for one root.';

COMMENT ON COLUMN "template"."lines"."template_id" IS E'The template that runs first (the root).';

COMMENT ON COLUMN "template"."lines"."version" IS E'Optimistic-concurrency version; starts at 1 and increases on every update.';

COMMENT ON TABLE "template"."patterns" IS E'A reviewed rule set about how one kind of body repeats (a county government, an election cycle). Its names are `identity.names`; its legal basis is `legal.effects` targeting this identity. `fromYear` is the year the pattern takes effect (2013 for counties).';

COMMENT ON COLUMN "template"."patterns"."code" IS E'Stable row code (`.docs/rules/codes.md`): lowercase, dot-separated, unique and never reused.';

COMMENT ON COLUMN "template"."patterns"."country_id" IS E'The country the pattern belongs to; empty means any country.';

COMMENT ON COLUMN "template"."patterns"."deleted_at" IS E'Soft-delete time; empty while the record is live.';

COMMENT ON COLUMN "template"."patterns"."from_year" IS E'First year of the period (negative for BCE); empty when the start is not known.';

COMMENT ON COLUMN "template"."patterns"."id" IS E'The identity this row extends: the same uuid as `identity.identities.id`.';

COMMENT ON COLUMN "template"."patterns"."identity_kind" IS E'Kind of the identity this row extends; with `id` it is a composite foreign key to `identity.identities (id, kind)`.';

COMMENT ON COLUMN "template"."patterns"."to_year" IS E'Last year of the period; empty while the period has not ended.';

COMMENT ON COLUMN "template"."patterns"."version" IS E'Optimistic-concurrency version; starts at 1 and increases on every update.';

COMMENT ON TABLE "template"."templates" IS E'The recipe for one kind of row: what it creates, over which places or items, how many, and with which attributes. Its names are `identity.names`; texts for codes, names, domains and contact values are `template.texts`.';

COMMENT ON COLUMN "template"."templates"."arm" IS E'Arm of the product.';

COMMENT ON COLUMN "template"."templates"."basis_term" IS E'Seat basis of the product. Term from vocabulary scheme `gov.seat.basis`.';

COMMENT ON COLUMN "template"."templates"."class_term" IS E'Institution class of the product. Term from vocabulary scheme `gov.institution.class`.';

COMMENT ON COLUMN "template"."templates"."code" IS E'Stable row code (`.docs/rules/codes.md`): lowercase, dot-separated, unique and never reused.';

COMMENT ON COLUMN "template"."templates"."confidence" IS E'How far the template''s expectation is trusted, 0 to 1. It is stated once here, never on the rows it creates.';

COMMENT ON COLUMN "template"."templates"."contact_kind" IS E'Contact kind of the product (email, website).';

COMMENT ON COLUMN "template"."templates"."contact_visibility" IS E'Visibility of the generated contact (public).';

COMMENT ON COLUMN "template"."templates"."contest_kind_term" IS E'Contest kind of the product (governor, member of parliament). Term from vocabulary scheme `ele.contest.kind`.';

COMMENT ON COLUMN "template"."templates"."count_kind" IS E'How the count is known: exact, a minimum, a maximum or a range. Slots are made for exact and minimum counts only.';

COMMENT ON COLUMN "template"."templates"."count_max" IS E'The maximum or the upper bound.';

COMMENT ON COLUMN "template"."templates"."count_min" IS E'The exact count, the minimum or the lower bound.';

COMMENT ON COLUMN "template"."templates"."deleted_at" IS E'Soft-delete time; empty while the record is live.';

COMMENT ON COLUMN "template"."templates"."election_kind_term" IS E'Election kind of the product (general). Term from vocabulary scheme `ele.election.kind`.';

COMMENT ON COLUMN "template"."templates"."election_past_status" IS E'Status for a cycle whose year has passed (held).';

COMMENT ON COLUMN "template"."templates"."election_status" IS E'Status the generated election starts with (scheduled).';

COMMENT ON COLUMN "template"."templates"."entity_kind_term" IS E'Organisation kind of an institution product (public body). Term from vocabulary scheme `ofc.entity.kind`.';

COMMENT ON COLUMN "template"."templates"."fan_out_level_id" IS E'The level the template fans out over; set for the level and within scopes only.';

COMMENT ON COLUMN "template"."templates"."id" IS E'The identity this row extends: the same uuid as `identity.identities.id`.';

COMMENT ON COLUMN "template"."templates"."identity_kind" IS E'Kind of the identity this row extends; with `id` it is a composite foreign key to `identity.identities (id, kind)`.';

COMMENT ON COLUMN "template"."templates"."kind_term" IS E'Institution kind of the product. Term from vocabulary scheme `gov.institution.kind`.';

COMMENT ON COLUMN "template"."templates"."method" IS E'Selection method of the product.';

COMMENT ON COLUMN "template"."templates"."premises_kind_term" IS E'Premises kind of the product (headquarters, regional office). Term from vocabulary scheme `ofc.premises.kind`.';

COMMENT ON COLUMN "template"."templates"."product" IS E'The kind of row this template creates.';

COMMENT ON COLUMN "template"."templates"."reason" IS E'Why the template expects its rows to exist (the law, convention or pattern behind it). Stated once here, never on the rows it creates.';

COMMENT ON COLUMN "template"."templates"."repeat_years" IS E'Cadence in years for products that repeat (election cycles, terms); the first year is the pattern''s `fromYear`.';

COMMENT ON COLUMN "template"."templates"."role_term" IS E'Position role of the product. Term from vocabulary scheme `gov.position.role`.';

COMMENT ON COLUMN "template"."templates"."scope" IS E'level: one per area at the level; within: one per area at the level inside the root''s area; list: one per item; single: one per root.';

COMMENT ON COLUMN "template"."templates"."sequence" IS E'Order in which the root templates of a pattern run (cycles before offices and terms).';

COMMENT ON COLUMN "template"."templates"."start_year" IS E'The first year this template produces; defaults to the pattern''s `fromYear` (Kenya''s first general election was 2013, later ones follow a five-year cycle from 2017).';

COMMENT ON COLUMN "template"."templates"."term_kind_term" IS E'Term kind of the product (parliamentary term, mandate). Term from vocabulary scheme `gov.term.kind`.';

COMMENT ON COLUMN "template"."templates"."version" IS E'Optimistic-concurrency version; starts at 1 and increases on every update.';

COMMENT ON TABLE "template"."texts" IS E'A text template for a code, a name per language, a web domain or a contact value.';

COMMENT ON COLUMN "template"."texts"."body" IS E'Text with named tokens and a closed list of transforms, such as `{county|slug}` or `{county|compact}.go.ke`.';

COMMENT ON COLUMN "template"."texts"."deleted_at" IS E'Soft-delete time; empty while the record is live.';

COMMENT ON COLUMN "template"."texts"."language_id" IS E'The language of a name; empty for codes, domains and contact values.';

COMMENT ON COLUMN "template"."texts"."name_kind" IS E'Kind of the generated name (official, short); set for names only.';

COMMENT ON COLUMN "template"."texts"."purpose" IS E'code, name, domain or contact value.';

COMMENT ON COLUMN "template"."texts"."version" IS E'Optimistic-concurrency version; starts at 1 and increases on every update.';

COMMENT ON TABLE "vocabulary"."labels" IS E'Every word for a term or scheme, per language and optional country. Labels have no dates; a changed meaning is a new term.';

COMMENT ON COLUMN "vocabulary"."labels"."country_id" IS E'Set when the same language words the term differently in one country.';

COMMENT ON COLUMN "vocabulary"."labels"."deleted_at" IS E'Soft-delete time; empty while the record is live.';

COMMENT ON COLUMN "vocabulary"."labels"."kind" IS E'What the text is for: preferred, plural, short, abbreviation, alternative or definition.';

COMMENT ON COLUMN "vocabulary"."labels"."language_id" IS E'Language of the text; never assumed to be English.';

COMMENT ON COLUMN "vocabulary"."labels"."scheme_id" IS E'The scheme this label words (its title or definition).';

COMMENT ON COLUMN "vocabulary"."labels"."term_id" IS E'The term this label words; exactly one of `term_id` and `scheme_id` is set.';

COMMENT ON COLUMN "vocabulary"."labels"."version" IS E'Optimistic-concurrency version; starts at 1 and increases on every update.';

COMMENT ON TABLE "vocabulary"."mappings" IS E'Links between terms across schemes and countries. Loops in broader and narrower links are refused by Mzizi''s write code.';

COMMENT ON COLUMN "vocabulary"."mappings"."from_id" IS E'The term the link starts from.';

COMMENT ON COLUMN "vocabulary"."mappings"."kind" IS E'broader, narrower, exact, close or related (SKOS mapping kinds).';

COMMENT ON COLUMN "vocabulary"."mappings"."to_id" IS E'The term it points at; may be in another scheme.';

COMMENT ON TABLE "vocabulary"."schemes" IS E'A controlled list such as feature kind, institution arm, topic, sex or age group. Its words are `vocabulary.labels`; it holds no display text.';

COMMENT ON COLUMN "vocabulary"."schemes"."answers" IS E'Whether a thing takes one live answer per period from this scheme, or many.';

COMMENT ON COLUMN "vocabulary"."schemes"."code" IS E'Stable row code (`.docs/rules/codes.md`): lowercase, dot-separated, unique and never reused.';

COMMENT ON COLUMN "vocabulary"."schemes"."country_id" IS E'Set only for a genuinely local scheme (a national budget classification); empty for a global scheme.';

COMMENT ON COLUMN "vocabulary"."schemes"."deleted_at" IS E'Soft-delete time; empty while the record is live.';

COMMENT ON COLUMN "vocabulary"."schemes"."is_dated" IS E'True when classifications from this scheme carry a valid period.';

COMMENT ON COLUMN "vocabulary"."schemes"."is_open" IS E'True when new terms may be added freely (tags); false for a closed, reviewed list.';

COMMENT ON COLUMN "vocabulary"."schemes"."shape" IS E'How the scheme''s terms are arranged: a flat list, a tree (parents) or a graph (mappings).';

COMMENT ON COLUMN "vocabulary"."schemes"."steward_id" IS E'The organisation that maintains the scheme (a statistics office, the UN); empty for Mzizi''s own.';

COMMENT ON COLUMN "vocabulary"."schemes"."version" IS E'Optimistic-concurrency version; starts at 1 and increases on every update.';

COMMENT ON TABLE "vocabulary"."scopes" IS E'Which kinds of named thing a scheme may classify.';

COMMENT ON COLUMN "vocabulary"."scopes"."identity_kind" IS E'A kind of identity this scheme may classify; checked by Mzizi''s code on `identity.classifications`.';

COMMENT ON TABLE "vocabulary"."terms" IS E'A member of one scheme: a code, its place in the scheme, display hints and optional numeric band. No display text: words are `vocabulary.labels`.';

COMMENT ON COLUMN "vocabulary"."terms"."code" IS E'Stable row code (`.docs/rules/codes.md`): lowercase, dot-separated, unique and never reused.';

COMMENT ON COLUMN "vocabulary"."terms"."color_token" IS E'Display hint: theme colour token for legends and chips.';

COMMENT ON COLUMN "vocabulary"."terms"."country_id" IS E'Set only for a genuinely local term (Nyumba Kumi); terms are global by default.';

COMMENT ON COLUMN "vocabulary"."terms"."deleted_at" IS E'Soft-delete time; empty while the record is live.';

COMMENT ON COLUMN "vocabulary"."terms"."icon_code" IS E'Display hint: icon code for legends and chips.';

COMMENT ON COLUMN "vocabulary"."terms"."lower" IS E'Lower bound of a numeric band (age 0–4 starts at 0), in `unit_id`.';

COMMENT ON COLUMN "vocabulary"."terms"."lower_inclusive" IS E'True when `lower` belongs to the band.';

COMMENT ON COLUMN "vocabulary"."terms"."parent_id" IS E'The broader term in a tree-shaped scheme (water body above lake); its ancestors are its categories.';

COMMENT ON COLUMN "vocabulary"."terms"."position" IS E'Display order among siblings; empty sorts by label.';

COMMENT ON COLUMN "vocabulary"."terms"."scheme_id" IS E'The scheme this term belongs to.';

COMMENT ON COLUMN "vocabulary"."terms"."status" IS E'Life of the term: active, deprecated or retired.';

COMMENT ON COLUMN "vocabulary"."terms"."supersedes_id" IS E'The older term this one replaces when a meaning changes; labels have no dates, terms carry history.';

COMMENT ON COLUMN "vocabulary"."terms"."unit_id" IS E'Unit of `lower` and `upper` (year, person, metre).';

COMMENT ON COLUMN "vocabulary"."terms"."upper" IS E'Upper bound of a numeric band; empty for an open band (age 65+).';

COMMENT ON COLUMN "vocabulary"."terms"."upper_inclusive" IS E'True when `upper` belongs to the band.';

COMMENT ON COLUMN "vocabulary"."terms"."version" IS E'Optimistic-concurrency version; starts at 1 and increases on every update.';
